window.RPH_DATA = {"tahun": 6, "mataPelajaran": "Sains", "sesi": 2026, "sekolah": "SK Kuala Betis", "entries": [{"id": 1, "title": "1.0 Kemahiran Saintifik (Pengenalan & Orientasi)", "minggu": 1, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Inkuiri dalam Sains", "topik": "1.0 Kemahiran Saintifik (Pengenalan & Orientasi)", "standardKandungan": "Orientasi Kurikulum dan Bilik Sains", "standardPembelajaran": "Pengenalan kepada kurikulum Sains Tahun 6 KSSR Semakan dan penggunaan Buku Teks Sains Tahun 6.", "objektifPembelajaran": "Di akhir PdP, murid dapat menerangkan struktur pembelajaran Sains Tahun 6 dan memahami kepentingan kemahiran saintifik dalam penyiasatan sains.", "kriteriaKejayaan": "Murid boleh menyenaraikan sekurang-kurangnya 5 unit pembelajaran yang akan dipelajari sepanjang tahun dan menyatakan kepentingan mematuhi peraturan bilik sains.", "setInduksi": "Guru menunjukkan buku teks Sains Tahun 6 (Semakan 2017) m/s 1 dan bertanya murid tentang jangkaan mereka terhadap topik yang bakal dipelajari. Murid memberi maklum balas ringkas tentang gambar rangsangan Unit 1.", "penyampaian": ["Murid diperkenalkan dengan 13 unit utama dalam subjek Sains Tahun 6 mengikut Kandungan (Buku Teks m/s iii-iv).", "Murid secara berpasangan meneliti m/s v-vi untuk memahami maksud dan kepentingan ikon-ikon dalam buku teks seperti 'Mari Uji', 'Aktiviti Ria', 'Santai Sains', 'Imbas Kembali', dan 'Asah Minda'.", "Guru membimbing murid membaca halaman rangsangan Unit 1 'Kemahiran Saintifik' (m/s 1) berkaitan cabaran model bangunan kalis taufan yang dihadapi oleh Alia.", "Murid membincangkan ramalan tentang model manakah (Model A, B, atau C) yang tidak mudah tumbang apabila ditiup angin serta memberikan alasan saintifik awal."], "penutup": "Murid membuat rumusan kognitif bahawa pembelajaran Sains Tahun 6 memerlukan pemikiran kritis, inkuiri, dan penguasaan kemahiran proses sains secara konsisten.", "pentaksiran": "Pemerhatian dan soal jawab lisan.", "bahanBantuBelajar": "Buku Teks Sains Tahun 6 SK m/s iii-vi, m/s 1.", "refleksi": ""}, {"id": 2, "title": "1.0 Kemahiran Saintifik", "minggu": 1, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Inkuiri dalam Sains", "topik": "1.0 Kemahiran Saintifik", "standardKandungan": "Pengenalan Kemahiran Proses Sains (KPS)", "standardPembelajaran": "Mengenal pasti 12 Kemahiran Proses Sains (KPS) yang perlu dikuasai berdasarkan Rujukan Buku Teks m/s 2.", "objektifPembelajaran": "Di akhir PdP, murid dapat menyenaraikan 12 Kemahiran Proses Sains (KPS) dengan betul berdasarkan sesi sumbang saran.", "kriteriaKejayaan": "Murid boleh memadankan sekurang-kurangnya 6 jenis KPS dengan deskripsi fungsinya secara tepat.", "setInduksi": "Guru menunjukkan sebuah kereta belon mainan yang bergerak di atas lantai dan meminta murid meneka proses sains yang terlibat untuk mengukur pergerakannya.", "penyampaian": ["Murid meneliti teks dan ilustrasi di m/s 2 berkaitan perbualan Raju dan rakan-rakannya tentang pembinaan kereta belon.", "Guru membentangkan 12 KPS (mempunyai ikon khusus di m/s 2) secara sistematik: memerhati, mengelas, mengukur dan menggunakan nombor, membuat inferens, meramal, berkomunikasi, menggunakan perhubungan ruang dan masa, mentafsir data, mendefinisi secara operasi, mengawal pemboleh ubah, membuat hipotesis, dan mengeksperimen.", "Murid secara berkumpulan membincangkan bagaimana Raju mengaplikasikan kemahiran proses sains tersebut dalam situasi harian.", "Murid menulis nama-nama KPS pada kad imbasan dan menyusunnya mengikut urutan logik penyiasatan."], "penutup": "Murid merumuskan bahawa kemahiran proses sains membantu mereka menyelesaikan masalah penyiasatan secara sistematik.", "pentaksiran": "Lembaran kerja padanan KPS dengan maksudnya.", "bahanBantuBelajar": "Kereta belon mainan, Kad imbasan KPS, Buku Teks m/s 2.", "refleksi": ""}, {"id": 3, "title": "1.0 Kemahiran Saintifik", "minggu": 2, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Inkuiri dalam Sains", "topik": "1.0 Kemahiran Saintifik", "standardKandungan": "1.1 Kemahiran Proses Sains", "standardPembelajaran": "1.1.1 Memerhati dengan menggunakan semua deria yang terlibat dan alat jika perlu untuk membuat pemerhatian secara kualitatif bagi menerangkan fenomena atau perubahan yang berlaku.", "objektifPembelajaran": "Di akhir PdP, murid dapat membuat pemerhatian kualitatif menggunakan sekurang-kurangnya tiga deria yang berbeza semasa membina 'Kereta Belon' berdasarkan halaman 2-3 Buku Teks.", "kriteriaKejayaan": "Murid boleh menyatakan sekurang-kurangnya tiga ciri fizikal bahan binaan kereta belon menggunakan deria penglihatan, sentuhan, dan pendengaran.", "setInduksi": "Guru membunyikan belon yang dilepaskan udaranya secara tiba-tiba dan meminta murid memerihalkan apa yang mereka dengar, lihat, dan rasa.", "penyampaian": ["Murid dibahagikan kepada kumpulan kecil untuk membina 'Kereta Belon' merujuk kepada langkah-langkah dalam Buku Teks m/s 2-3.", "Murid menggunakan deria penglihatan untuk mengukur panjang penyedut minuman tidak boleh lentur (11 cm) dan lidi sate (15 cm) menggunakan pembaris.", "Semasa langkah menebuk lubang penutup botol (Buku Teks m/s 3, Langkah 4), murid membuat pemerhatian tentang kekerasan penutup botol menggunakan deria sentuhan (merasa tekanan fizikal).", "Murid memerhatikan perubahan fizikal belon yang mengembang apabila ditiup dan mengecil apabila udara dilepaskan (Buku Teks m/s 3)."], "penutup": "Murid merumuskan bahawa deria penglihatan, sentuhan, dan pendengaran sangat penting untuk mengumpul maklumat secara kualitatif semasa fasa pembinaan produk sains.", "pentaksiran": "Pemerhatian semasa amali pembinaan kereta belon.", "bahanBantuBelajar": "Botol plastik, penutup botol, lidi sate, penyedut minuman, belon, gunting, pita pelekat, Buku Teks m/s 2-3.", "refleksi": ""}, {"id": 4, "title": "1.0 Kemahiran Saintifik", "minggu": 2, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Inkuiri dalam Sains", "topik": "1.0 Kemahiran Saintifik", "standardKandungan": "1.1 Kemahiran Proses Sains", "standardPembelajaran": "1.1.2 Mengelas dengan membandingkan atau mengenal pasti persamaan dan perbezaan berdasarkan ciri sepunya.", "objektifPembelajaran": "Di akhir PdP, murid dapat mengelaskan pelbagai komponen kereta belon kepada kumpulan bahan terbiodegradasi dan tidak terbiodegradasi dengan betul.", "kriteriaKejayaan": "Murid boleh membina satu carta pengelasan bagi komponen kereta belon berdasarkan ciri sepunya bahan dengan tepat.", "setInduksi": "Guru menunjukkan dua kumpulan bahan: botol plastik dan lidi sate kayu, lalu bertanya murid tentang perbezaan ketara sifat kedua-dua bahan tersebut.", "penyampaian": ["Murid meneliti komponen kereta belon yang telah dibina (Buku Teks m/s 4). Murid mengenal pasti bahan sepunya seperti botol, penutup botol, dan penyedut minuman (bahan berasaskan plastik).", "Murid membandingkan persamaan dan perbezaan ciri fizikal bahan tersebut dengan lidi sate (berasaskan kayu) dan belon (berasaskan getah).", "Murid dibimbing mengelaskan semua komponen binaan ini kepada dua kategori utama: Bahan Berasaskan Plastik (botol, penutup botol, penyedut minuman) dan Bahan Bukan Plastik (lidi sate, belon, pita pelekat).", "Murid membina carta pengelasan kreatif dalam buku nota masing-masing berpandukan konsep pengelasan m/s 4."], "penutup": "Murid membuat refleksi kognitif bahawa kemahiran mengelas membantu menyusun data atau objek yang pelbagai kepada kumpulan yang teratur mengikut ciri sepunya.", "pentaksiran": "Carta pengelasan komponen dalam buku latihan.", "bahanBantuBelajar": "Komponen binaan kereta belon, kertas mahjung, Buku Teks m/s 4.", "refleksi": ""}, {"id": 5, "title": "1.0 Kemahiran Saintifik", "minggu": 3, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Inkuiri dalam Sains", "topik": "1.0 Kemahiran Saintifik", "standardKandungan": "1.1 Kemahiran Proses Sains", "standardPembelajaran": "1.1.3 Mengukur dan menggunakan nombor dengan menggunakan alat dan unit piawai dengan teknik yang betul.", "objektifPembelajaran": "Di akhir PdP, murid dapat mengukur jarak pergerakan kereta belon dalam unit sentimeter ($cm$) menggunakan pembaris meter dengan teknik yang betul.", "kriteriaKejayaan": "Murid boleh membaca skala pembaris dengan kedudukan mata yang betul (mengelakkan ralat paralaks) dan merekodkan sekurang-kurangnya tiga bacaan jarak yang jitu.", "setInduksi": "Guru menunjukkan pembaris yang patah hujungnya dan bertanya bagaimana hendak memulakan pengukuran jarak secara tepat tanpa skala sifar yang sempurna.", "penyampaian": ["Murid merujuk kepada perbualan Alia dan Chua di Buku Teks m/s 5 tentang kaedah mengukur jarak pergerakan kereta belon.", "Guru menerangkan teknik pengukuran yang betul: memastikan hujung belakang kereta diletakkan pada garisan permulaan (skala 0 cm) dan membaca kedudukan akhir kereta selepas berhenti dengan kedudukan mata bersudut tegak ($90^\\circ$) di atas skala pembaris.", "Murid secara bergilir-gilir menguji pergerakan kereta belon masing-masing dan mengukur jarak pergerakannya menggunakan pembaris meter.", "Murid menulis nilai ukuran beserta unit piawai sentimeter ($cm$) secara jelas dalam lembaran aktiviti."], "penutup": "Murid merumuskan kepentingan kedudukan mata yang betul semasa mengukur untuk mendapatkan data kuantitatif yang tepat dan sah.", "pentaksiran": "Amali mengukur jarak pergerakan kereta belon.", "bahanBantuBelajar": "Pembaris meter, pita pelekat (garisan permulaan), kereta belon, Buku Teks m/s 5.", "refleksi": ""}, {"id": 6, "title": "1.0 Kemahiran Saintifik", "minggu": 3, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Inkuiri dalam Sains", "topik": "1.0 Kemahiran Saintifik", "standardKandungan": "1.1 Kemahiran Proses Sains", "standardPembelajaran": "1.1.4 Membuat inferens dengan menyatakan kesimpulan awal atau penerangan yang munasabah bagi sesuatu pemerhatian dengan menggunakan maklumat yang diperoleh.", "objektifPembelajaran": "Di akhir PdP, murid dapat menulis sekurang-kurangnya satu inferens munasabah bagi menerangkan perbezaan jarak pergerakan kereta belon yang berbeza berdasarkan isi padu udara di dalam belon.", "kriteriaKejayaan": "Murid boleh menghubungkaitkan pemerhatian jarak pergerakan kereta belon dengan jumlah tenaga/udara tersimpan di dalam belon secara logik.", "setInduksi": "Guru menunjukkan dua kereta belon: satu bergerak sejauh 38 cm dan satu lagi hanya 12 cm, lalu bertanyakan mengapa situasi itu berlaku.", "penyampaian": ["Murid menganalisis perbualan Raju dan rakan-rakan di m/s 6 Buku Teks tentang punca kereta belon Alia bergerak paling dekat (12 cm) berbanding Chua (38 cm).", "Murid dibimbing untuk mengaitkan pemerhatian: 'Kereta belon Alia bergerak dekat' dengan sebabnya: 'kerana saiz belon Alia sangat kecil dan udara di dalamnya sangat sedikit'.", "Guru menjelaskan struktur penulisan inferens: Pemerhatian + Kerana + Alasan Sains.", "Murid secara individu menulis draf inferens bagi tiga situasi pergerakan kereta belon yang berbeza saiz belonnya."], "penutup": "Murid merumuskan bahawa membuat inferens adalah proses menerangkan 'mengapa' sesuatu pemerhatian berlaku berdasarkan bukti dan pengetahuan sains lalu.", "pentaksiran": "Lembaran kerja menulis inferens.", "bahanBantuBelajar": "Data jarak pergerakan kereta belon (m/s 6), Buku Teks m/s 6.", "refleksi": ""}, {"id": 7, "title": "1.0 Kemahiran Saintifik", "minggu": 4, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Inkuiri dalam Sains", "topik": "1.0 Kemahiran Saintifik", "standardKandungan": "1.1 Kemahiran Proses Sains", "standardPembelajaran": "1.1.5 Meramal dengan membuat jangkaan tentang sesuatu peristiwa atau fenomena berdasarkan pemerhatian, pengalaman lalu atau data.", "objektifPembelajaran": "Di akhir PdP, murid dapat membuat satu ramalan berasaskan data tentang arah pergerakan dan jarak kereta belon sekiranya saiz belon ditingkatkan melebihi had asal.", "kriteriaKejayaan": "Murid boleh menyatakan ramalan jarak (dalam bentuk nilai nombor jangkaan) berdasarkan pola aliran data terdahulu dengan logik.", "setInduksi": "Guru menunjukkan sebiji belon bersaiz sederhana dan bertanya: \"Jika saya tiup belon ini dua kali ganda lebih besar, ramalkan apa yang akan berlaku kepada jarak pergerakan kereta belon?\"", "penyampaian": ["Murid merujuk kepada m/s 7 Buku Teks di mana Chua dan Jesy membincangkan perubahan jisim kereta belon.", "Murid menganalisis data jarak sedia ada (12 cm, 30 cm, 38 cm) yang sepadan dengan saiz belon kecil, sederhana, dan besar (Buku Teks m/s 6).", "Murid membuat ramalan: Sekiranya saiz belon diisi udara sehingga diameter 15 cm (sangat besar), jarak pergerakan kereta belon diramal akan melebihi 38 cm (contoh: 45 cm).", "Murid menguji ramalan mereka dengan menjalankan aktiviti pelancaran kereta belon menggunakan belon super besar dan mengukur jarak sebenar untuk membandingkan dengan ramalan."], "penutup": "Murid membuat kesimpulan bahawa meramal bukan sekadar meneka, tetapi merupakan jangkaan bijak berdasarkan pemerhatian, pengalaman lalu, atau trend data.", "pentaksiran": "Soal jawab draf ramalan murid dan verifikasi data.", "bahanBantuBelajar": "Kereta belon, belon pelbagai saiz, pembaris meter, Buku Teks m/s 6-7.", "refleksi": ""}, {"id": 8, "title": "1.0 Kemahiran Saintifik", "minggu": 4, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Inkuiri dalam Sains", "topik": "1.0 Kemahiran Saintifik", "standardKandungan": "1.1 Kemahiran Proses Sains", "standardPembelajaran": "1.1.6 Berkomunikasi dengan merekod maklumat atau idea dalam bentuk yang sesuai dan mempersembahkan maklumat atau idea tersebut secara sistematik.", "objektifPembelajaran": "Di akhir PdP, murid dapat membina satu jadual sistematik untuk merekod dan mengomunikasikan data jarak pergerakan tiga jenis kereta belon dengan kemas.", "kriteriaKejayaan": "Murid boleh melukis jadual dengan lajur yang betul bagi 'Nama Kereta' dan 'Jarak (cm)' serta mengisinya berdasarkan data eksperimen dengan tepat.", "setInduksi": "Guru menulis data pergerakan kereta belon secara berselerak di papan tulis dan meminta murid membincangkan kesukaran membaca data tersebut.", "penyampaian": ["Murid meneliti contoh jadual komunikasi yang dibina oleh Chua di Buku Teks m/s 6.", "Guru menerangkan pelbagai kaedah berkomunikasi dalam sains: jadual, graf, carta palang, lakaran, atau lisan.", "Murid secara berkumpulan berbincang untuk memindahkan data pergerakan mentah kumpulan mereka ke dalam bentuk jadual komunikasi yang kemas di atas kertas mahjung.", "Wakil kumpulan membentangkan hasil jadual mereka di hadapan kelas secara lisan dengan menerangkan perbezaan prestasi setiap kereta secara sistematik."], "penutup": "Murid merumuskan bahawa komunikasi yang sistematik (seperti jadual) memudahkan orang lain membaca, memahami, dan menganalisis data sains yang diperoleh.", "pentaksiran": "Hasil jadual dalam buku latihan murid dan pembentangan kumpulan.", "bahanBantuBelajar": "Kertas mahjung, pen penanda, Buku Teks m/s 6.", "refleksi": ""}, {"id": 9, "title": "1.0 Kemahiran Saintifik", "minggu": 5, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Inkuiri dalam Sains", "topik": "1.0 Kemahiran Saintifik", "standardKandungan": "1.1 Kemahiran Proses Sains", "standardPembelajaran": "1.1.7 Menggunakan perhubungan ruang dan masa dengan menyusun kejadian sesuatu fenomena atau peristiwa mengikut kronologi berdasarkan masa.", "objektifPembelajaran": "Di akhir PdP, murid dapat menyusun urutan perubahan saiz belon mengikut kronologi masa semasa kereta belon bergerak dengan betul.", "kriteriaKejayaan": "Murid boleh menerangkan bagaimana parameter isi padu belon berubah (berkurang) apabila parameter masa bertambah semasa pergerakan objek.", "setInduksi": "Guru menunjukkan gambar fasa-fasa lilin yang menyala dari panjang sehingga cair sepenuhnya dan meminta murid menyusun gambar tersebut mengikut masa.", "penyampaian": ["Murid merujuk kepada Buku Teks m/s 7, memerhatikan dialog Raju dan Chua tentang perubahan saiz belon semasa bergerak.", "Murid menjalankan amali singkat: melancarkan kereta belon dan merakam atau memerhatikan keadaan belon pada saat ke-0, saat ke-2, saat ke-4, dan saat ke-6.", "Murid mendapati secara kronologi: 'semakin lama kereta bergerak (masa bertambah), saiz belon menjadi semakin mengecil (isi padu berkurang)'.", "Murid melukis draf lakaran kronologi perubahan bentuk belon daripada besar kepada kempis mengikut sela masa pergerakan kereta."], "penutup": "Murid merumuskan bahawa hubungan ruang dan masa menerangkan bagaimana sesuatu parameter (seperti bentuk atau saiz) berubah mengikut perubahan masa.", "pentaksiran": "Lakaran kronologi sela pergerakan dan saiz belon dalam buku log.", "bahanBantuBelajar": "Kereta belon, jam randik, Buku Teks m/s 7.", "refleksi": ""}, {"id": 10, "title": "1.0 Kemahiran Saintifik", "minggu": 5, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Inkuiri dalam Sains", "topik": "1.0 Kemahiran Saintifik", "standardKandungan": "1.1 Kemahiran Proses Sains", "standardPembelajaran": "1.1.8 Mentafsir data dengan memilih idea yang relevan tentang objek, peristiwa atau pola yang terdapat pada data untuk membuat penerangan.", "objektifPembelajaran": "Di akhir PdP, murid dapat mentafsir jadual data pergerakan kereta belon untuk menentukan kereta yang paling laju dan membuat kesimpulan yang relevan.", "kriteriaKejayaan": "Murid boleh menyatakan hubungan pola (trend) antara saiz belon dengan jarak pergerakan berdasarkan data m/s 6 dengan betul.", "setInduksi": "Guru mengemukakan soalan mencabar: \"Berdasarkan jadual m/s 6, kereta siapakah yang paling cekap menggunakan tenaga udara? Bagaimanakah kita tahu?\"", "penyampaian": ["Murid mengkaji jadual data di m/s 6: Kereta Chua (38 cm), Alia (12 cm), dan Raju (30 cm).", "Guru membimbing murid mentafsir data: Kereta Chua mempunyai nilai nombor tertinggi (38 cm), bermaksud ia bergerak paling jauh. Kereta Alia mempunyai nilai terendah (12 cm), bermaksud ia bergerak paling dekat.", "Murid mengenal pasti pola: 'Semakin bertambah saiz belon (isi padu udara), semakin bertambah jarak pergerakan kereta belon.'", "Murid menulis satu ulasan bertulis ringkas (mentafsir data) untuk menerangkan prestasi pergerakan kereta berdasarkan jadual tersebut."], "penutup": "Murid merumuskan bahawa mentafsir data membolehkan kita memberi penerangan rasional tentang pola atau hubungan tersembunyi di sebalik data yang dikumpul.", "pentaksiran": "Latihan bertulis mentafsir data jadual m/s 6.", "bahanBantuBelajar": "Jadual data pergerakan (Buku Teks m/s 6), Buku Teks m/s 6.", "refleksi": ""}, {"id": 11, "title": "1.0 Kemahiran Saintifik", "minggu": 6, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Inkuiri dalam Sains", "topik": "1.0 Kemahiran Saintifik", "standardKandungan": "1.1 Kemahiran Proses Sains", "standardPembelajaran": "1.1.9 Mendefinisi secara operasi dengan memerihalkan satu tafsiran tentang perkara yang dilakukan dan diperhatikan bagi sesuatu situasi mengikut aspek yang ditentukan.", "objektifPembelajaran": "Di akhir PdP, murid dapat menulis satu definisi secara operasi bagi 'kelajuan kereta belon' berdasarkan apa yang dilakukan dan diperhatikan dalam penyiasatan.", "kriteriaKejayaan": "Murid boleh menyatakan aspek yang diuji (jarak pergerakan kereta belon) dan aspek yang diperhatikan (pemenang perlumbaan/masa) dengan tepat menggunakan struktur DSO yang betul.", "setInduksi": "Guru bertanya kepada kelas: \"Bagaimanakah kita boleh mengukur 'kecerdasan' seorang murid secara operasi di dalam bilik darjah?\" (Contoh: Melalui markah ujian). Ini bagi memperkenalkan konsep definisi secara operasi.", "penyampaian": ["Murid meneliti perbincangan di m/s 7 Buku Teks tentang menentukan kereta belon yang paling laju.", "Chua menyatakan: \"kereta belon yang bergerak paling laju ialah kereta belon yang dapat bergerak paling jauh dalam eksperimen ini.\"", "Guru membimbing murid membina DSO: 'Kelajuan kereta belon ditunjukkan oleh jarak yang dilalui oleh kereta belon tersebut dalam perlumbaan'.", "Murid berlatih menulis DSO bagi parameter lain seperti 'kekuatan belon' (ditunjukkan oleh bilangan hembusan udara sebelum pecah)."], "penutup": "Murid merumuskan bahawa definisi secara operasi menerangkan sesuatu pemboleh ubah dengan menyatakan perkara yang perlu dilakukan dan diperhatikan.", "pentaksiran": "Latihan bertulis membina definisi secara operasi bagi kelajuan kereta belon.", "bahanBantuBelajar": "Buku Teks m/s 7, papan tulis, lembaran DSO.", "refleksi": ""}, {"id": 12, "title": "1.0 Kemahiran Saintifik", "minggu": 6, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Inkuiri dalam Sains", "topik": "1.0 Kemahiran Saintifik", "standardKandungan": "1.1 Kemahiran Proses Sains", "standardPembelajaran": "1.1.10 Mengawal pemboleh ubah dengan menentukan pemboleh ubah bergerak balas dan dimalarkan setelah pemboleh ubah dimanipulasi ditentukan dalam sesuatu penyiasatan.", "objektifPembelajaran": "Di akhir PdP, murid dapat menentukan pemboleh ubah dimanipulasi (PM), pemboleh ubah bergerak balas (PB), dan pemboleh ubah dimalarkan (PD) bagi Eksperimen 'Jisim Mempengaruhi Jarak Pergerakan Kereta Belon' (Buku Teks m/s 8).", "kriteriaKejayaan": "Murid boleh menyenaraikan PM (bilangan duit syiling 10 sen/jisim kereta), PB (jarak pergerakan kereta belon), dan PD (saiz belon/jenis botol) dengan tepat.", "setInduksi": "Guru menunjukkan dua kereta belon: satu kosong dan satu lagi sarat dengan muatan syiling, lalu bertanya: \"Apakah pemboleh ubah yang sengaja saya ubah antara kedua-dua kereta ini?\"", "penyampaian": ["Murid meneliti rancangan eksperimen di Buku Teks m/s 8: 'Jisim Mempengaruhi Jarak Pergerakan Kereta Belon'.", "Guru menjelaskan maksud tiga jenis pemboleh ubah: dimanipulasi (perkara yang sengaja diubah), bergerak balas (perkara yang diperhatikan/diukur), dan dimalarkan (perkara yang dikekalkan sama).", "Murid menganalisis senarai alat dan bahan m/s 8, termasuk penggunaan '12 keping duit syiling 10 sen' sebagai pemberat untuk memanipulasi jisim kereta.", "Murid secara berpasangan melengkapkan borang perancangan pemboleh ubah bagi eksperimen tersebut secara sistematik."], "penutup": "Murid membuat kesimpulan bahawa mengawal pemboleh ubah sangat kritikal untuk memastikan eksperimen dijalankan secara adil (*fair test*).", "pentaksiran": "Pengisian borang pemboleh ubah eksperimen.", "bahanBantuBelajar": "Kereta belon, duit syiling 10 sen, Buku Teks m/s 8.", "refleksi": ""}, {"id": 13, "title": "1.0 Kemahiran Saintifik", "minggu": 7, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Inkuiri dalam Sains", "topik": "1.0 Kemahiran Saintifik", "standardKandungan": "1.1 Kemahiran Proses Sains", "standardPembelajaran": "1.1.11 Membuat hipotesis dengan membuat pernyataan umum yang boleh diuji tentang hubungan antara pemboleh ubah dalam sesuatu penyiasatan. 1.1.12 Mengeksperimen dengan menggunakan kemahiran proses sains asas bagi mengumpul dan mentafsir data serta membuat rumusan untuk membuktikan hipotesis dan membuat laporan.", "objektifPembelajaran": "Di akhir PdP, murid dapat menjalankan eksperimen lengkap, menulis hipotesis, dan menyediakan laporan eksperimen 'Jisim Mempengaruhi Jarak Pergerakan Kereta Belon' (m/s 8) dengan betul.", "kriteriaKejayaan": "Murid boleh membuktikan hipotesis: \"Semakin bertambah jisim kereta belon, semakin berkurang jarak pergerakannya\" melalui pengumpulan data eksperimen yang tepat.", "setInduksi": "Guru mencabar murid melancarkan kereta belon bermuatan penuh dan kosong secara serentak di atas trek, murid membuat inferens awal tentang hasilnya.", "penyampaian": ["Murid merancang eksperimen mengikut format laporan di m/s 8 Buku Teks: Tujuan, Penyataan Masalah, Hipotesis, Pemboleh Ubah, Alat/Bahan, Langkah, Data, Mentafsir Data, dan Kesimpulan.", "Murid menjalankan eksperimen secara berkumpulan: menguji kereta belon tanpa syiling (0g), dengan 4 keping syiling, 8 keping syiling, dan 12 keping syiling sebagai PM.", "Murid mengukur dan merekodkan jarak pergerakan kereta (PB) bagi setiap pusingan ujian sebanyak tiga kali untuk mendapatkan purata yang jitu.", "Kumpulan membincangkan tafsiran data dan merumuskan sama ada hipotesis mereka diterima atau ditolak."], "penutup": "Murid merumuskan bahawa mengeksperimen adalah kemahiran proses sains tertinggi yang menyatukan semua kemahiran proses yang lain untuk membuktikan kebenaran hipotesis.", "pentaksiran": "Penulisan laporan eksperimen bertulis yang lengkap dalam buku amali.", "bahanBantuBelajar": "Kereta belon, duit syiling, pita pelekat, pembaris meter, Buku Teks m/s 8.", "refleksi": ""}, {"id": 14, "title": "1.0 Kemahiran Saintifik", "minggu": 7, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Inkuiri dalam Sains", "topik": "1.0 Kemahiran Saintifik", "standardKandungan": "1.2 Kemahiran Manipulatif", "standardPembelajaran": "1.2.1-1.2.5 Mengguna, mengendali, melakar, membersih dan menyimpan peralatan, bahan dan spesimen sains dengan betul.", "objektifPembelajaran": "Di akhir PdP, murid dapat mengamalkan lima kemahiran manipulatif dengan betul semasa menguruskan peralatan eksperimen kereta belon.", "kriteriaKejayaan": "Murid boleh membersihkan tempat kerja dan menyusun serta menyimpan semula gunting, pembaris, sisa botol, dan alat tulis di tempat yang dikhasan dengan selamat.", "setInduksi": "Guru menunjukkan bilik sains yang berselerak dengan sisa plastik dan gunting tajam di atas meja, bertanya tentang risiko keselamatan yang boleh berlaku.", "penyampaian": ["Guru menerangkan 5 peraturan utama Kemahiran Manipulatif (SP 1.2.1-1.2.5) termasuk pengendalian peralatan tajam (gunting) dengan selamat.", "Murid mempraktikkan cara membersihkan sisa potongan pita pelekat atau plastik botol yang digunakan semasa eksperimen kereta belon.", "Murid mengasingkan bahan buangan mengikut kategori terbiodegradasi (lidi kayu) dan tidak terbiodegradasi (botol plastik) sebelum dibuang ke dalam bakul sampah yang betul.", "Murid menyusun pembaris meter, baki belon, dan gunting ke dalam kabinet stor sains mengikut label keselamatan."], "penutup": "Murid membuat ikrar untuk sentiasa mempraktikkan kemahiran manipulatif yang betul demi keselamatan diri dan kebersihan bilik sains.", "pentaksiran": "Senarai semak kemahiran manipulatif (pemerhatian guru).", "bahanBantuBelajar": "Kabinet penyimpanan radas, bakul sampah pengasingan, Buku Teks m/s 8.", "refleksi": ""}, {"id": 15, "title": "2.0 Peraturan Bilik Sains", "minggu": 8, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Inkuiri dalam Sains", "topik": "2.0 Peraturan Bilik Sains", "standardKandungan": "2.1 Peraturan Bilik Sains", "standardPembelajaran": "2.1.1 Mematuhi peraturan bilik sains bagi menjamin kelancaran PdP serta keselamatan pengguna.", "objektifPembelajaran": "Di akhir PdP, murid dapat menyenaraikan dan menerangkan sekurang-kurangnya 5 Peraturan Bilik Sains asas berkaitan kebenaran guru dan amalan keselamatan diri.", "kriteriaKejayaan": "Murid boleh menerangkan mengapa tindakan melanggar peraturan bilik sains (seperti makan atau bermain) boleh mendatangkan bahaya fizikal.", "setInduksi": "Guru menunjukkan sebotol air minuman di atas meja makmal bersebelahan dengan cecair kimia jernih, meminta murid memikirkan risiko jika terminum cecair tersebut secara tidak sengaja.", "penyampaian": ["Murid meneliti teks m/s 12-13 Buku Teks berkaitan keselamatan pengguna di dalam Bilik Sains.", "Guru menerangkan peraturan penting: masuk hanya dengan kebenaran guru, dilarang makan, minum, atau bermain di dalam bilik sains, serta sentiasa mematuhi arahan guru semasa menjalankan eksperimen.", "Murid secara berkumpulan membincangkan Situasi 1: Kesan jika murid membawa masuk makanan ringan (risiko kontaminasi sisa bahan kimia eksperimen terdahulu).", "Murid melakonkan simulasi pendek menunjukkan amalan yang betul semasa memasuki bilik sains dengan beratur di luar kelas dan menunggu guru."], "penutup": "Murid merumuskan bahawa pematuhan Peraturan Bilik Sains adalah tanggungjawab bersama bagi menjamin keselamatan dan kelancaran proses pembelajaran.", "pentaksiran": "Kuiz lisan/bertulis mengenai Peraturan Bilik Sains.", "bahanBantuBelajar": "Poster Peraturan Bilik Sains, Buku Teks m/s 12-13.", "refleksi": ""}, {"id": 16, "title": "2.0 Peraturan Bilik Sains", "minggu": 8, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Inkuiri dalam Sains", "topik": "2.0 Peraturan Bilik Sains", "standardKandungan": "2.1 Peraturan Bilik Sains", "standardPembelajaran": "2.1.1 Mematuhi peraturan bilik sains bagi menjamin kelancaran PdP serta keselamatan pengguna.", "objektifPembelajaran": "Di akhir PdP, murid dapat menerangkan tindakan kecemasan yang betul sekiranya berlaku kemalangan atau tumpahan bahan kimia di dalam bilik sains.", "kriteriaKejayaan": "Murid boleh menyatakan prosedur melaporkan kejadian tumpahan atau kerosakan peralatan kepada guru dengan segera tanpa melengahkan masa.", "setInduksi": "Guru menjatuhkan bikar plastik kosong ke lantai untuk menghasilkan bunyi impak dan bertanya kepada murid: \"Apakah tindakan pertama kamu jika ini adalah bikar kaca berisi asid?\"", "penyampaian": ["Murid merujuk halaman Peraturan Bilik Sains (Buku Teks m/s 12-13) mengenai aspek tindak balas kecemasan.", "Guru menerangkan langkah pertama: Jangan panik, jangan cuba membersihkan tumpahan asid/kaca sendiri, sebaliknya laporkan segera kepada guru mata pelajaran.", "Murid mempelajari langkah pembersihan yang selamat oleh guru (menggunakan pasir untuk menyerap tumpahan bahan kimia).", "Murid melakukan simulasi mencuci tangan di sinki sekiranya terkena bahan kimia secara tidak sengaja mengikut aliran air yang berterusan."], "penutup": "Murid membuat refleksi kognitif bahawa tindakan pantas melaporkan kemalangan boleh mengelakkan kecederaan yang lebih serius.", "pentaksiran": "Lembaran kerja padanan situasi kemalangan dengan tindakan yang betul.", "bahanBantuBelajar": "Carta alir kecemasan, Buku Teks m/s 12-13.", "refleksi": ""}, {"id": 17, "title": "2.0 Manusia", "minggu": 9, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Sains Hayat", "topik": "2.0 Manusia", "standardKandungan": "2.1 Pembiakan Manusia", "standardPembelajaran": "2.1.1 Memerihalkan fungsi organ pembiakan lelaki (testis, zakar) dan perempuan (faraj, ovari, tiub fallopio, uterus).", "objektifPembelajaran": "Di akhir PdP, murid dapat melabel dan menerangkan fungsi organ pembiakan lelaki (testis dan zakar) serta perempuan (faraj, uterus, tiub Fallopio, ovari) dengan betul berdasarkan rajah Buku Teks m/s 14-15.", "kriteriaKejayaan": "Murid boleh melengkapkan tugasan melabel sekurang-kurangnya 5 daripada 6 organ pembiakan berserta fungsinya secara tepat.", "setInduksi": "Guru memaparkan gambar situasi di dewan bersalin (Buku Teks m/s 12-13) dan memulakan perbincangan tentang bagaimana bayi boleh terhasil melalui organ pembiakan khusus.", "penyampaian": ["Murid meneliti gambar rajah 'Organ Pembiakan Lelaki' di m/s 14 Buku Teks. Guru menerangkan fungsi testis (tempat sperma dihasilkan) dan zakar (menyalurkan sperma ke dalam organ pembiakan perempuan).", "Murid meneliti gambar rajah 'Organ Pembiakan Perempuan' di m/s 15 Buku Teks. Guru menerangkan fungsi: faraj (saluran menerima sperma), ovari (menghasilkan ovum), tiub Fallopio (tempat persenyawaan), dan uterus/rahim (tempat embrio berkembang).", "Murid secara berpasangan menjalankan aktiviti melabel organ pada kad aktiviti yang disediakan.", "Murid membincangkan info sains m/s 15 tentang kemungkinan kelahiran bayi kembar sekiranya ovari membebaskan lebih daripada satu ovum pada satu-satu masa."], "penutup": "Murid merumuskan fungsi asas sistem pembiakan lelaki dan perempuan sebagai sistem hidup penting untuk kelangsungan generasi manusia.", "pentaksiran": "Lembaran kerja melabel organ pembiakan lelaki dan perempuan.", "bahanBantuBelajar": "Kad gambar rajah organ pembiakan, Buku Teks m/s 14-15.", "refleksi": ""}, {"id": 18, "title": "2.0 Manusia", "minggu": 9, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Sains Hayat", "topik": "2.0 Manusia", "standardKandungan": "2.1 Pembiakan Manusia", "standardPembelajaran": "2.1.2 Menjelaskan proses persenyawaan manusia sehingga bayi dilahirkan.", "objektifPembelajaran": "Di akhir PdP, murid dapat menyusun dan menjelaskan 5 fasa proses persenyawaan manusia sehingga bayi dilahirkan mengikut urutan kronologi yang betul (m/s 16-17 Buku Teks).", "kriteriaKejayaan": "Murid boleh menyatakan maksud persenyawaan (percantuman sperma dan ovum) dan menerangkan fasa pertukaran sel dari zigot, embrio, fetus, sehingga bayi dengan tepat.", "setInduksi": "Guru menayangkan klip animasi 3D pendek tentang perjalanan jutaan sperma ke arah satu ovum dan bertanya apa yang berlaku apabila percantuman terjadi.", "penyampaian": ["Murid merujuk kronologi visual proses persenyawaan hingga kelahiran bayi di m/s 16-17 Buku Teks.", "Guru menerangkan fasa demi fasa secara terperinci:", "Murid dibahagikan kepada kumpulan untuk menyusun kad kronologi 'zigot -> embrio -> fetus -> bayi' di atas kad manila."], "penutup": "Murid membuat rumusan kognitif tentang keajaiban proses persenyawaan dan perkembangan bayi dalam rahim ibu.", "pentaksiran": "Penyusunan kad kronologi proses pembiakan manusia secara berkumpulan.", "bahanBantuBelajar": "Set kad kronologi fasa persenyawaan, Buku Teks m/s 16-17.", "refleksi": ""}, {"id": 19, "title": "2.0 Manusia", "minggu": 10, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Sains Hayat", "topik": "2.0 Manusia", "standardKandungan": "2.1 Pembiakan Manusia", "standardPembelajaran": "2.1.3 Penaakul kepentingan pembiakan kepada manusia.", "objektifPembelajaran": "Di akhir PdP, murid dapat menaakul sekurang-kurangnya dua kepentingan utama proses pembiakan kepada manusia dari aspek pertambahan bilangan populasi dan pengelakan kepupusan spesies.", "kriteriaKejayaan": "Murid boleh memberikan hujah rasional tentang kesan sekiranya manusia berhenti menjalankan pembiakan secara total berdasarkan analisis situasi m/s 18 Buku Teks.", "setInduksi": "Guru menunjukkan gambar sebuah silsilah keluarga (family tree) yang besar dan bertanya apa yang berlaku jika generasi datuk/nenek tidak membiak.", "penyampaian": ["Murid meneliti Situasi 1 di m/s 18 Buku Teks tentang pertambahan bilangan keluarga Encik Ahmad daripada 2 orang kepada 12 orang.", "Murid menganalisis Situasi 2 (m/s 18 Buku Teks) yang menggambarkan keadaan Bumi yang sunyi tanpa manusia sekiranya pembiakan terhenti.", "Murid secara berkumpulan membincangkan soalan: \"Apakah yang akan terjadi kepada kemandirian spesies manusia jika manusia tidak membiak?\"", "Setiap kumpulan membentangkan hujah taakulan mereka (contoh: manusia akan pupus, tiada lagi pewaris tamadun, kepincangan struktur masyarakat)."], "penutup": "Murid merumuskan kepentingan pembiakan untuk kelangsungan generasi dan mengekalkan populasi manusia di muka Bumi.", "pentaksiran": "Penulisan esei pendek taakulan kepentingan pembiakan dalam buku latihan.", "bahanBantuBelajar": "Gambar rajah situasi 1 & 2 Buku Teks m/s 18.", "refleksi": ""}, {"id": 20, "title": "2.0 Manusia", "minggu": 10, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Sains Hayat", "topik": "2.0 Manusia", "standardKandungan": "2.1 Pembiakan Manusia", "standardPembelajaran": "2.1.4 Menjelaskan pemerhatian tentang pembiakan manusia melalui lakaran, TMK, penulisan atau lisan secara kreatif.", "objektifPembelajaran": "Di akhir PdP, murid dapat menghasilkan satu poster kreatif (e-poster atau fizikal) bertajuk 'Sistem Pembiakan Manusia' secara berkumpulan mengikut langkah Buku Teks m/s 19.", "kriteriaKejayaan": "Murid boleh mempamerkan poster yang mengandungi gambar organ pembiakan yang dilabel dengan betul dan kronologi persenyawaan yang tepat serta membentangkannya di dalam kelas.", "setInduksi": "Guru menunjukkan contoh e-poster menarik tentang kesihatan pembiakan untuk mencetuskan idea kreatif murid.", "penyampaian": ["Murid dibahagikan kepada kumpulan dan diarahkan untuk menjalankan 'Aktiviti Ria: Poster Pembiakan Manusia' (Buku Teks m/s 19).", "Murid melukis atau mencetak gambar rajah organ pembiakan (menggunakan kod QR m/s 19) dan menampalnya pada kad manila.", "Murid secara berkumpulan membincangkan, melabel, dan menerangkan fungsi organ pembiakan lelaki dan perempuan secara kreatif menggunakan pen penanda berwarna-warni.", "Murid menulis kronologi persenyawaan manusia hingga bayi dilahirkan mengikut urutan yang telah dipelajari di m/s 16-17.", "Murid mengadakan sesi pameran bilik darjah (Gallery Walk) di mana ketua kumpulan membentangkan hasil kerja manakala ahli lain menilai poster kumpulan rakan."], "penutup": "Murid membuat refleksi tentang kepentingan mengomunikasikan maklumat sains secara grafik dan kreatif supaya mudah difahami oleh orang lain.", "pentaksiran": "Penilaian portfolio (Poster Pembiakan Manusia).", "bahanBantuBelajar": "Kad manila, pen penanda, gambar rajah bercetak (m/s 19), Buku Teks m/s 19.", "refleksi": ""}, {"id": 21, "title": "2.0 Manusia (Sistem Saraf)", "minggu": 11, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Sains Hayat", "topik": "2.0 Manusia (Sistem Saraf)", "standardKandungan": "2.2 Sistem Saraf", "standardPembelajaran": "2.2.1 Mengenal pasti jenis sistem saraf manusia (pusat dan periferi).", "objektifPembelajaran": "Di akhir PdP, murid dapat menamakan dua jenis sistem saraf manusia dan komponen utama yang terlibat (pusat dan periferi) dengan betul berdasarkan gambar rajah Buku Teks m/s 21.", "kriteriaKejayaan": "Murid boleh melukis draf kedudukan otak, saraf tunjang, dan rangkaian saraf pada tubuh manusia secara kasar dengan tepat.", "setInduksi": "Guru meminta murid menyentuh lutut mereka secara tiba-tiba dan bertanya: \"Apakah yang menghantarkan arahan dari otak kamu untuk menggerakkan jari tangan menyentuh lutut?\"", "penyampaian": ["Murid meneliti teks m/s 20-21 Buku Teks berkaitan pengenalan sistem saraf yang mengawal koordinasi gerak balas badan terhadap rangsangan.", "Guru menerangkan dua jenis sistem saraf: Sistem Saraf Pusat (terdiri daripada otak dan saraf tunjang) dan Sistem Saraf Periferi (terdiri daripada rangkaian saraf di seluruh tubuh).", "Murid secara berpasangan mengenal pasti label komponen sistem saraf pada ilustrasi tubuh manusia m/s 21.", "Murid melengkapkan lembaran tugasan melukis dan menamakan bahagian sistem saraf manusia."], "penutup": "Murid membuat rumusan bahawa sistem saraf manusia adalah pusat kawalan utama yang membahagikan tugasan antara pusat (otak, saraf tunjang) dan periferi (rangkaian saraf).", "pentaksiran": "Lembaran kerja melabel jenis sistem saraf.", "bahanBantuBelajar": "Gambar rajah sistem saraf manusia, Buku Teks m/s 20-21.", "refleksi": ""}, {"id": 22, "title": "2.0 Manusia (Sistem Saraf)", "minggu": 11, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Sains Hayat", "topik": "2.0 Manusia (Sistem Saraf)", "standardKandungan": "2.2 Sistem Saraf", "standardPembelajaran": "2.2.2 Memerihalkan sistem saraf pusat (otak, saraf tunjang) dan fungsinya. 2.2.3 Menyatakan fungsi sistem saraf periferi.", "objektifPembelajaran": "Di akhir PdP, murid dapat membezakan fungsi otak (tindakan terkawal dan luar kawal), fungsi saraf tunjang (tindakan refleks), serta fungsi sistem saraf periferi dengan betul (Buku Teks m/s 22-25).", "kriteriaKejayaan": "Murid boleh memberikan 3 contoh tindakan terkawal, 3 contoh tindakan luar kawal, dan 2 contoh tindakan refleks yang dikawal oleh sistem saraf pusat dengan tepat.", "setInduksi": "Guru melakukan aksi mengetuk meja secara perlahan di sebelah telinga murid (tindakan terkawal) dan meniup mata murid dengan perlahan (tindakan refleks) untuk menunjukkan perbezaan tindak balas.", "penyampaian": ["Murid membaca teks m/s 22-23 Buku Teks. Guru menerangkan peranan otak dalam mengkoordinasi tindakan terkawal (makan, menari, menulis) dan luar kawal (pernafasan, denyutan jantung, pencernaan).", "Murid mengkaji peranan saraf tunjang di m/s 24 dalam membawa maklumat ke seluruh tubuh dan mengawal tindakan refleks (seperti menarik tangan apabila tersentuh benda panas atau bersin apabila hidung dimasuki habuk).", "Guru menjelaskan fungsi sistem saraf periferi (m/s 25) iaitu menghantar isyarat dari bahagian tubuh ke sistem saraf pusat, dan menghantar isyarat arahan dari sistem saraf pusat ke seluruh bahagian tubuh.", "Murid membuat peta minda pengelasan tindakan sistem saraf di dalam buku nota."], "penutup": "Murid merumuskan aliran isyarat dari rangsangan -> organ deria -> sistem saraf pusat -> gerak balas yang berlaku dalam masa kurang dari satu saat (m/s 23).", "pentaksiran": "Pembinaan peta minda fungsi sistem saraf pusat dan periferi.", "bahanBantuBelajar": "Buku Teks m/s 22-25, kad imbasan jenis tindakan.", "refleksi": ""}, {"id": 23, "title": "2.0 Manusia (Sistem Saraf)", "minggu": 12, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Sains Hayat", "topik": "2.0 Manusia (Sistem Saraf)", "standardKandungan": "2.2 Sistem Saraf", "standardPembelajaran": "2.2.4 Meramalkan keadaan yang berlaku jika sistem saraf periferi tidak berfungsi.", "objektifPembelajaran": "Di akhir PdP, murid dapat meramalkan sekurang-kurangnya dua implikasi kegagalan fungsi sistem saraf periferi terhadap pergerakan dan keseimbangan tubuh manusia berdasarkan situasi m/s 25 Buku Teks.", "kriteriaKejayaan": "Murid boleh menerangkan simptom penyakit Bell's palsy dan masalah keseimbangan badan akibat kegagalan sistem saraf periferi secara lisan dengan betul.", "setInduksi": "Guru menunjukkan gambar seseorang yang separuh mukanya herot akibat lumpuh saraf muka dan bertanya murid tentang jangkaan kerosakan sistem saraf yang berlaku.", "penyampaian": ["Murid meneliti teks m/s 25 Buku Teks berkaitan penyakit Bell's palsy (keadaan kerosakan saraf periferi otot muka menyebabkan separuh muka herot, sukar tersenyum atau menutup mata).", "Murid menganalisis keadaan kehilangan keseimbangan tubuh semasa berjalan akibat kerosakan saraf di bahagian kaki (Buku Teks m/s 25).", "Murid secara berkumpulan membincangkan kesan sekiranya isyarat arahan dari otak tidak sampai ke kaki semasa terpijak paku tajam.", "Murid menulis rumusan bertulis ramalan kegagalan fungsi sistem saraf periferi dalam bentuk esei ulasan ringkas."], "penutup": "Murid membuat refleksi kognitif tentang kepentingan menghargai kesihatan rangkaian sistem saraf periferi yang utuh.", "pentaksiran": "Jawapan bertulis analisis ramalan kegagalan saraf periferi.", "bahanBantuBelajar": "Gambar pesakit Bell's palsy, Buku Teks m/s 25.", "refleksi": ""}, {"id": 24, "title": "2.0 Manusia (Sistem Saraf)", "minggu": 12, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Sains Hayat", "topik": "2.0 Manusia (Sistem Saraf)", "standardKandungan": "2.2 Sistem Saraf", "standardPembelajaran": "2.2.5 Menjana idea tentang cara menjaga sistem saraf. 2.2.6 Menjelaskan pemerhatian tentang sistem saraf melalui pelbagai media secara kreatif.", "objektifPembelajaran": "Di akhir PdP, murid dapat menyenaraikan 5 amalan penjagaan kesihatan sistem saraf dan mempersembahkan simulasi aliran isyarat saraf secara kreatif berdasarkan Buku Teks m/s 26-28.", "kriteriaKejayaan": "Murid boleh menyenaraikan pemakanan sihat, postur yang betul, tidur mencukupi, pengelakan alkohol, serta peralatan perlindungan fizikal untuk memelihara saraf dengan tepat.", "setInduksi": "Guru menunjukkan topi keledar dan bertanya: \"Apakah hubung kait penggunaan alat pelindung ini dengan penjagaan sistem saraf pusat kita?\"", "penyampaian": ["Murid meneliti teks m/s 26-27 Buku Teks tentang cara menjaga sistem saraf: makan makanan seimbang (Vitamin B kompleks), elakkan minuman beralkohol, tidur mencukupi (7-8 jam), memakai alat pelindung tubuh (topi keledar, pelindung belakang), dan mengamalkan postur yang betul.", "Murid dibahagikan kepada kumpulan untuk menjalankan 'Aktiviti Ria: Aktiviti Isyarat Sistem Saraf' (Buku Teks m/s 28).", "Setiap kumpulan melukis bentuk badan rakan di atas kertas mahjung, menampal gambar otak dan saraf tunjang, serta menggunakan benang untuk mewakili sistem saraf periferi.", "Murid melakukan simulasi aliran isyarat (contoh: situasi terhidu bau masakan) dengan menunjukkan aliran isyarat dari hidung -> saraf periferi -> otak -> bergerak balas dengan menyebut nama organ terlibat."], "penutup": "Murid merumuskan aktiviti dengan menyatakan komitmen untuk mengamalkan gaya hidup sihat demi kecergasan sistem saraf.", "pentaksiran": "Penilaian amali projek Isyarat Sistem Saraf dan kerjasama berkumpulan.", "bahanBantuBelajar": "Kertas mahjung, benang, gambar organ, gunting, pita pelekat, Buku Teks m/s 26-28.", "refleksi": ""}, {"id": 25, "title": "3.0 Mikroorganisma", "minggu": 13, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Sains Hayat", "topik": "3.0 Mikroorganisma", "standardKandungan": "3.1 Proses Hidup & Kesan Mikroorganisma", "standardPembelajaran": "3.1.1 Menjelas dengan contoh jenis mikroorganisma (fungi, protozoa, alga, bakteria, virus). 3.1.2 Mengitlak maksud mikroorganisma.", "objektifPembelajaran": "Di akhir PdP, murid dapat mengitlak maksud mikroorganisma dan mengelaskan lima kumpulan mikroorganisma berserta satu contoh spesifik bagi setiap kumpulan dengan betul berdasarkan m/s 34-35 Buku Teks.", "kriteriaKejayaan": "Murid boleh memberikan maksud mikroorganisma (hidupan seni tidak dapat dilihat dengan mata kasar) dan menyatakan contoh mikroorganisma seperti Penicillium, Salmonella, Volvox, Amoeba, dan HIV dengan tepat.", "setInduksi": "Guru menunjukkan sekeping roti yang berkulat hitam dan bertanya murid: \"Apakah organisma yang menumpang pada roti ini? Bolehkah kita melihatnya secara terperinci tanpa mikroskop?\"", "penyampaian": ["Murid membaca m/s 34-35 Buku Teks untuk memahami istilah 'mikro' (seni/halus) dan 'organisma' (hidupan). Murid mengitlak bahawa mikroorganisma ialah hidupan seni yang tidak dapat dilihat dengan mata kasar.", "Guru menerangkan lima jenis mikroorganisma utama:", "Murid secara berpasangan membina kad padanan kategori mikroorganisma dan membuat kuiz kilat sesama rakan kelas."], "penutup": "Murid merumuskan bahawa alam mikroorganisma sangat luas dan terdiri daripada pelbagai bentuk hidupan seni yang hidup di sekeliling kita.", "pentaksiran": "Lembaran kerja pengkelasan jenis-jenis mikroorganisma.", "bahanBantuBelajar": "Gambar mikroorganisma m/s 34-35, Kad padanan, Buku Teks m/s 34-35.", "refleksi": ""}, {"id": 26, "title": "3.0 Mikroorganisma", "minggu": 13, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Sains Hayat", "topik": "3.0 Mikroorganisma", "standardKandungan": "3.1 Proses Hidup & Kesan Mikroorganisma", "standardPembelajaran": "3.1.3 Memerihalkan proses hidup mikroorganisma (bernafas, bertumbuh, bergerak) dengan menjalankan penyiasatan.", "objektifPembelajaran": "Di akhir PdP, murid dapat memerihalkan tiga proses hidup mikroorganisma (bernafas, bergerak, bertumbuh) berdasarkan hasil tiga aktiviti amali 'Mari Uji' di m/s 36-39 Buku Teks dengan betul.", "kriteriaKejayaan": "Murid boleh menerangkan bukti mikroorganisma bernafas (belon mengembang), bergerak (perubahan kedudukan protozoa di bawah mikroskop), dan bertumbuh (peningkatan saiz kulapuk roti) dengan tepat.", "setInduksi": "Guru menunjukkan sepeket yis kering aktif dan air suam, lalu bertanya kepada murid: \"Adakah yis di dalam peket ini bernafas dan hidup? Bagaimanakah kita boleh membuktikannya?\"", "penyampaian": ["Aktiviti 1 (Mikroorganisma Bernafas): Murid menjalankan eksperimen menggunakan yis, gula, air suam, dan botol plastik yang dipasang belon (m/s 36-37). Murid menggoncangkan botol, menyukat ukur lilit belon setiap 10 minit selama 30 minit, dan merumuskan belon mengembang kerana pembebasan gas karbon dioksida daripada pernafasan yis.", "Aktiviti 2 (Mikroorganisma Bergerak): Murid menggunakan mikroskop untuk memerhati pergerakan organisma (Amoeba/Paramesium) dalam setitis air kolam (m/s 37-38). Murid melakar kedudukan mikroorganisma pada minit ke-1, ke-2, dan ke-3.", "Aktiviti 3 (Mikroorganisma Bertumbuh): Murid menyembur air pada roti, memasukkannya ke dalam beg plastik berzip, menyimpannya di tempat gelap (m/s 39). Murid menganalisis pertumbuhan saiz kulapuk roti dari hari ke-5 hingga ke-7."], "penutup": "Murid membuat kesimpulan umum bahawa mikroorganisma ialah benda hidup kerana menjalankan proses asas pernafasan, pergerakan, dan pertumbuhan.", "pentaksiran": "Laporan aktiviti amali proses hidup mikroorganisma.", "bahanBantuBelajar": "Yis, gula, belon, botol, air kolam, mikroskop, roti, beg plastik berzip, Buku Teks m/s 36-39.", "refleksi": ""}, {"id": 27, "title": "3.0 Mikroorganisma", "minggu": 14, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Sains Hayat", "topik": "3.0 Mikroorganisma", "standardKandungan": "3.1 Proses Hidup & Kesan Mikroorganisma", "standardPembelajaran": "3.1.4 Mengeksperimen untuk menentukan faktor yang mempengaruhi pertumbuhan mikroorganisma (suhu, nutrien, keasidan, air, udara).", "objektifPembelajaran": "Di akhir PdP, murid dapat membuktikan faktor suhu yang sesuai mempengaruhi pertumbuhan mikroorganisma melalui eksperimen kerosakan susu di m/s 41 Buku Teks dengan betul.", "kriteriaKejayaan": "Murid boleh menyatakan pemboleh ubah eksperimen (PM: suhu susu, PB: keadaan susu selepas 3 hari, PD: kuantiti susu) dan menulis hipotesis yang boleh diuji dengan tepat.", "setInduksi": "Guru meletakkan sekotak susu segar di atas meja makmal dan sekotak lagi di dalam peti sejuk, lalu meminta murid meramal susu yang manakah akan rosak dahulu selepas tiga hari.", "penyampaian": ["Murid membincangkan keperluan asas pertumbuhan mikroorganisma berpandukan dialog di m/s 40 Buku Teks.", "Murid merancang 'Eksperimen: Suhu yang Sesuai' mengikut format di m/s 41 Buku Teks.", "Murid menyiasat susu segar dalam tiga botol:", "Murid mengkaji keadaan susu segar tersebut selama tiga hari dan mentafsirkan data bahawa suhu bilik (Botol B) adalah suhu yang paling sesuai untuk pertumbuhan bakteria (susu cepat berasid/rosak)."], "penutup": "Murid merumuskan bahawa suhu yang sangat rendah atau sangat tinggi dapat menghalang atau menghentikan aktiviti dan pertumbuhan mikroorganisma.", "pentaksiran": "Penulisan laporan eksperimen faktor suhu.", "bahanBantuBelajar": "Susu segar, botol berpenutup, penunu Bunsen, termos, peti sejuk, Buku Teks m/s 41.", "refleksi": ""}, {"id": 28, "title": "3.0 Mikroorganisma", "minggu": 14, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Sains Hayat", "topik": "3.0 Mikroorganisma", "standardKandungan": "3.1 Proses Hidup & Kesan Mikroorganisma", "standardPembelajaran": "3.1.4 Mengeksperimen untuk menentukan faktor yang mempengaruhi pertumbuhan mikroorganisma (suhu, nutrien, keasidan, air, udara).", "objektifPembelajaran": "Di akhir PdP, murid dapat menerangkan bagaimana kehadiran air, udara, nutrien, dan keasidan mempengaruhi pertumbuhan mikroorganisma melalui cadangan eksperimen ringkas di m/s 42-44 Buku Teks.", "kriteriaKejayaan": "Murid boleh memadankan kaedah rawatan bahan (contoh: pengeringan roti, bungkusan vakum, larutan cuka) dengan faktor pertumbuhan mikroorganisma yang cuba disingkirkan.", "setInduksi": "Guru menunjukkan biskut kering (tahan lama) dan roti basah (cepat berkulat) untuk memulakan perbincangan tentang faktor kelembapan (air).", "penyampaian": ["Murid mengkaji faktor kehadiran air (m/s 42): membandingkan roti kering (Roti A) dengan roti basah yang dicelup air (Roti B) bagi melihat pertumbuhan kulapuk.", "Murid mengkaji faktor kehadiran udara (m/s 42-43): membandingkan kepingan epal dalam pek vakum (tiada udara) dengan epal terdedah (ada udara) bagi menghalang kulat.", "Murid mengkaji faktor kehadiran nutrien (m/s 43): membandingkan pertumbuhan bakteria di dalam air suling (tiada nutrien) dengan susu segar (ada nutrien).", "Murid mengkaji faktor keasidan (m/s 44): membandingkan hirisan mangga dalam cuka (keasidan tinggi tidak sesuai untuk pertumbuhan) dengan mangga dalam air pili."], "penutup": "Murid melengkapkan kesimpulan menyeluruh tentang 5 faktor pertumbuhan mikroorganisma (suhu, air, udara, nutrien, keasidan) dalam bentuk formula akronim yang mudah diingati.", "pentaksiran": "Kuiz pengukuhan 5 faktor pertumbuhan mikroorganisma.", "bahanBantuBelajar": "Roti kering/basah, epal, pek vakum, air suling, susu segar, cuka, Buku Teks m/s 42-44.", "refleksi": ""}, {"id": 29, "title": "3.0 Mikroorganisma", "minggu": 15, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Sains Hayat", "topik": "3.0 Mikroorganisma", "standardKandungan": "3.1 Proses Hidup & Kesan Mikroorganisma", "standardPembelajaran": "3.1.5 Memerihalkan kesan tindakan mikroorganisma dalam kehidupan harian.", "objektifPembelajaran": "Di akhir PdP, murid dapat membahagikan kesan tindakan mikroorganisma kepada 4 kebaikan (pembuatan makanan, perubatan, baja, sisa) dan 6 keburukan (penyakit, kerosakan makanan/tanaman, reput gigi) dengan betul berdasarkan Buku Teks m/s 44-46.", "kriteriaKejayaan": "Murid boleh memberikan contoh khusus bakteria Salmonella (keracunan makanan) dan kulat Penicillium (penghasilan antibiotik) serta fungsinya.", "setInduksi": "Guru menunjukkan sebotol yakult/yogurt dan sekotak antibiotik penisilin, bertanya murid tentang fungsi kedua-dua produk tersebut yang menggunakan mikroorganisma.", "penyampaian": ["Murid meneliti teks 'Kegunaan Mikroorganisma' m/s 44-45 Buku Teks: pembuatan makanan (keju, tempe, roti, yogurt, tapai), penghasilan ubat (antibiotik penisilin, vaksin), penghasilan baja organik (penguraian tinja), dan perawatan sisa kumbahan.", "Murid meneliti 'Keburukan Mikroorganisma' m/s 45-46 Buku Teks: merosakkan makanan, mereputkan gigi (bakteria menghasilkan asid daripada gula), keracunan makanan (Salmonella), kerosakan tanaman, dan penyakit berjangkit (Influenza, kurap, beguk, campak).", "Murid secara berkumpulan membina kad minda membandingkan kesan baik dan buruk mikroorganisma.", "Sesi perbincangan interaktif tentang bagaimana penyakit beguk dan campak disebarkan oleh virus."], "penutup": "Murid merumuskan bahawa tidak semua mikroorganisma berbahaya; sesetengahnya memberi sumbangan kritikal dalam teknologi kehidupan manusia.", "pentaksiran": "Peta pemikiran banding beza kesan mikroorganisma.", "bahanBantuBelajar": "Yogurt, antibiotik kosong, kad gambar penyakit, Buku Teks m/s 44-46.", "refleksi": ""}, {"id": 30, "title": "3.0 Mikroorganisma", "minggu": 15, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Sains Hayat", "topik": "3.0 Mikroorganisma", "standardKandungan": "3.1 Proses Hidup & Kesan Mikroorganisma", "standardPembelajaran": "3.1.5 Memerihalkan kesan tindakan mikroorganisma dalam kehidupan harian. 3.1.6 Menjelaskan pemerhatian tentang mikroorganisma melalui lakaran, TMK, penulisan atau lisan secara kreatif.", "objektifPembelajaran": "Di akhir PdP, murid dapat menjalankan projek 'Terarium Kulat' mengikut prosedur Buku Teks m/s 47 dengan selamat dan membentangkan hasilnya secara lisan yang kreatif.", "kriteriaKejayaan": "Murid boleh menerangkan bagaimana kulat bertindak ke atas sisa makanan di dalam terarium tertutup tanpa membuka penutupnya demi keselamatan.", "setInduksi": "Guru menunjukkan bekas lut sinar kosong dan bertanya murid: \"Bagaimanakah kita boleh membina sebuah hutan mini mikroorganisma (kulat) di dalam bekas ini menggunakan sisa makanan?\"", "penyampaian": ["Murid dibimbing memahami peraturan keselamatan projek di m/s 47 Buku Teks: Dilarang membuka penutup bekas terarium kulat yang telah siap, dan dilarang menyentuh kulapuk dengan tangan kosong.", "Murid menjalankan 'Aktiviti Ria: Terarium Kulat' (Buku Teks m/s 47): menyusun sisa makanan (roti, kulit buah, nasi) secara berjarak di dalam bekas berpenutup jernih, menyembur sedikit air, dan menutup bekas dengan kemas.", "Murid membuat ramalan awal: Sisa makanan manakah yang akan rosak dahulu? Apakah jenis kulat yang akan kelihatan? (Buku Teks m/s 47).", "Murid membentangkan pelan pemantauan terarium mereka (pemerhatian setiap tiga hari selama enam hari) secara berkumpulan di hadapan kelas."], "penutup": "Murid merumuskan kepentingan menjaga kebersihan dan amalan melupuskan terarium kulat secara selamat mengikut arahan guru di akhir projek.", "pentaksiran": "Penilaian kemandirian idea dan ramalan ilmiah dalam lembaran kerja Terarium Kulat.", "bahanBantuBelajar": "Bekas jernih, sisa makanan, penyembur air, kertas catatan, Buku Teks m/s 47.", "refleksi": ""}, {"id": 31, "title": "4.0 Interaksi antara Hidupan", "minggu": 16, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Sains Hayat", "topik": "4.0 Interaksi antara Hidupan", "standardKandungan": "4.1 Interaksi antara Haiwan", "standardPembelajaran": "4.1.1 Memerihalkan jenis interaksi antara hidupan (mangsa-pemangsa, persaingan, simbiosis).", "objektifPembelajaran": "Di akhir PdP, murid dapat menerangkan konsep interaksi mangsa-pemangsa dan mengelaskan haiwan pemangsa dengan mangsa yang betul berdasarkan contoh m/s 52-53 Buku Teks.", "kriteriaKejayaan": "Murid boleh menyatakan maksud pemangsa (haiwan yang memburu) dan mangsa (haiwan yang diburu) serta mengenal pasti penyu-ikan, helang-arnab, dan labah-labah-belalang secara tepat.", "setInduksi": "Guru mempamerkan gambar citah yang berlari mengejar rusa (m/s 52) dan meminta murid menerangkan jenis hubungan yang sedang berlaku dalam aksi tersebut.", "penyampaian": ["Murid meneliti teks pengenalan m/s 52 Buku Teks tentang maksud interaksi antara hidupan (hubungan saling bergantung untuk keperluan asas demi meneruskan hidup).", "Guru menerangkan definisi Pemangsa (memburu haiwan lain) dan Mangsa (haiwan yang diburu atau dimakan).", "Murid mengkaji info sains m/s 52 tentang tumbuhan pemangsa (pokok perangkap lalat Venus) yang memburu serangga kecil seperti lalat.", "Murid secara berpasangan menganalisis senarai gambar m/s 53 (penyu-ikan, burung helang-ular, burung-belalang, labah-labah-belalang, obor-obor-ikan kecil) untuk mengelaskan pemangsa dan mangsa dalam jadual pengelasan."], "penutup": "Murid merumuskan bahawa interaksi mangsa-pemangsa adalah sebahagian daripada kitaran rantai makanan semula jadi yang mengekalkan keseimbangan populasi haiwan.", "pentaksiran": "Latihan bertulis pengelasan pemangsa dan mangsa.", "bahanBantuBelajar": "Gambar interaksi haiwan m/s 52-53, Buku Teks m/s 52-53.", "refleksi": ""}, {"id": 32, "title": "4.0 Interaksi antara Hidupan", "minggu": 16, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Sains Hayat", "topik": "4.0 Interaksi antara Hidupan", "standardKandungan": "4.1 Interaksi antara Haiwan", "standardPembelajaran": "4.1.2 Menjelas dengan contoh faktor persaingan bagi haiwan intraspesies dan interspesies.", "objektifPembelajaran": "Di akhir PdP, murid dapat membezakan faktor persaingan haiwan intraspesies (4 faktor) dan interspesies (3 faktor) berserta contoh yang betul (Buku Teks m/s 53-55).", "kriteriaKejayaan": "Murid boleh menaakul mengapa faktor 'pasangan' hanya wujud pada persaingan intraspesies tetapi tidak wujud pada persaingan interspesies dengan tepat.", "setInduksi": "Guru menunjukkan gambar sekumpulan dubuk berebut seketul daging (Buku Teks m/s 54) dan meminta murid menyatakan faktor perebutan tersebut.", "penyampaian": ["Guru menerangkan maksud intraspesies (spesies yang sama) dan interspesies (spesies berbeza).", "Murid mengkaji Faktor Persaingan Intraspesies di m/s 54 Buku Teks:", "Murid mengkaji Faktor Persaingan Interspesies di m/s 55 Buku Teks:", "Murid menganalisis perbezaan kedua-dua persaingan tersebut dan membentangkan rumusan dalam bentuk Peta Buih Berganda."], "penutup": "Murid membuat kesimpulan bahawa persaingan berlaku apabila sumber keperluan asas dalam sesuatu habitat adalah terhad.", "pentaksiran": "Peta Buih Berganda (Faktor Persaingan Haiwan).", "bahanBantuBelajar": "Kad gambar persaingan haiwan m/s 54-55, Buku Teks m/s 53-55.", "refleksi": ""}, {"id": 33, "title": "4.0 Interaksi antara Hidupan", "minggu": 17, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Sains Hayat", "topik": "4.0 Interaksi antara Hidupan", "standardKandungan": "4.1 Interaksi antara Haiwan", "standardPembelajaran": "4.1.3 Menjelaskan melalui contoh jenis interaksi simbiosis antara haiwan (mutualisme, komensalisme, parasitisme).", "objektifPembelajaran": "Di akhir PdP, murid dapat menerangkan tiga jenis simbiosis haiwan (mutualisme, parasitisme, komensalisme) berserta satu contoh bagi setiap jenis dengan betul (m/s 56-57 Buku Teks).", "kriteriaKejayaan": "Murid boleh menyatakan maksud simbiosis sebagai hubungan rapat antara dua spesies haiwan yang berbeza dan mengenal pasti kesan hubungan tersebut (+/+, +/-, +/o) dengan tepat.", "setInduksi": "Guru menceritakan hubungan unik burung kecil yang mematuk celah gigi buaya yang sedang ternganga dan meminta murid membincangkan manfaat yang diperoleh oleh kedua-dua pihak.", "penyampaian": ["Guru membentangkan tiga jenis Simbiosis:", "Murid dibahagikan kepada pasangan untuk melengkapkan kad pengelasan hubungan (+/+, +/-, +/o) yang mewakili setiap senario simbiosis.", "Murid membincangkan info sains m/s 56 tentang bagaimana sengat pada buran melindungi ikan badut."], "penutup": "Murid membuat rumusan bertulis pengelasan simbiosis haiwan dalam jadual yang kemas.", "pentaksiran": "Jadual klasifikasi jenis simbiosis haiwan.", "bahanBantuBelajar": "Kad hubungan simbiosis, Buku Teks m/s 56-57.", "refleksi": ""}, {"id": 34, "title": "4.0 Interaksi antara Hidupan", "minggu": 17, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Sains Hayat", "topik": "4.0 Interaksi antara Hidupan", "standardKandungan": "4.1 Interaksi antara Haiwan", "standardPembelajaran": "4.1.4 Menjelaskan pemerhatian tentang interaksi antara haiwan secara kreatif.", "objektifPembelajaran": "Di akhir PdP, murid dapat melakonkan sekurang-kurangnya satu jenis interaksi antara haiwan (pemangsa-mangsa, persaingan, atau simbiosis) secara berkumpulan dengan yakin melalui aktiviti drama pendek (m/s 58 Buku Teks).", "kriteriaKejayaan": "Murid boleh menghasilkan topi kon haiwan yang kreatif dan melakonkan dialog sains yang menggambarkan jenis interaksi terpilih dengan tepat.", "setInduksi": "Guru mencabut satu kad dari kotak misteri dan membuat mimik muka serta aksi haiwan tertentu (contoh: kucing yang sedang tergaru-garu akibat sengkenit).", "penyampaian": ["Murid dibimbing untuk merancang aktiviti berdasarkan 'Aktiviti Ria: Drama Interaksi' (Buku Teks m/s 58).", "Setiap kumpulan menghasilkan topi kon kertas berbentuk rupa haiwan (seperti buaya, singa, ketam, teritip, atau burung) menggunakan kad manila, stapler, dan gelang getah.", "Kumpulan mencabut undi jenis interaksi (Mangsa-Pemangsa, Persaingan, atau Simbiosis) daripada kotak.", "Murid bekerjasama melakonkan aksi interaksi tersebut di hadapan kelas selama 3 minit, manakala ahli kumpulan lain meneka jenis interaksi yang dipersembahkan."], "penutup": "Murid merumuskan aktiviti dengan membincangkan pengajaran tentang bagaimana interaksi ini mengekalkan keseimbangan alam semula jadi.", "pentaksiran": "Penilaian prestasi lakonan kreatif dan aplikasi konsep sains dalam drama.", "bahanBantuBelajar": "Kad manila, stapler, gelang getah, kotak undian, gunting, Buku Teks m/s 58.", "refleksi": ""}, {"id": 35, "title": "4.0 Interaksi antara Hidupan", "minggu": 18, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Sains Hayat", "topik": "4.0 Interaksi antara Hidupan", "standardKandungan": "4.2 Interaksi antara Tumbuhan", "standardPembelajaran": "4.2.1 Memerihalkan faktor persaingan antara tumbuhan dengan menjalankan penyiasatan.", "objektifPembelajaran": "Di akhir PdP, murid dapat mengenal pasti empat faktor persaingan antara tumbuhan (air, cahaya matahari, nutrien, ruang) berdasarkan perancangan empat aktiviti penyiasatan 'Mari Uji' di m/s 59-62 Buku Teks.", "kriteriaKejayaan": "Murid boleh menerangkan kesan kekurangan air, cahaya, ruang, atau nutrien terhadap saiz, ketinggian, dan kesihatan akar anak pokok kacang hijau melalui analisis eksperimen dengan tepat.", "setInduksi": "Guru menunjukkan dua pasu anak pokok cili: pasu A tumbuh subur, manakala pasu B tumbuh tinggi lampai, kurus, dan layu. Murid berbincang tentang puncanya.", "penyampaian": ["Murid meneliti teks pengenalan m/s 59 Buku Teks tentang faktor-faktor yang menyebabkan tumbuhan bersaing sesama sendiri untuk terus hidup.", "Guru membentangkan draf reka bentuk 4 Aktiviti Penyiasatan 'Mari Uji' (m/s 59-62):", "Murid merekodkan ramalan keputusan dan melukis draf penyusunan pasu bagi keempat-empat eksperimen tersebut dalam buku amali."], "penutup": "Murid membuat kesimpulan umum bahawa tumbuhan bersaing untuk mendapatkan keperluan asas yang terhad (cahaya matahari, air, nutrien, dan ruang) bagi memastikan kemandirian mereka.", "pentaksiran": "Lembaran kerja lakaran reka bentuk dan ramalan penyiasatan tumbuhan.", "bahanBantuBelajar": "Pasu, benih kacang hijau, tanah, kotak, baja, Buku Teks m/s 59-62.", "refleksi": ""}, {"id": 36, "title": "4.0 Interaksi antara Hidupan", "minggu": 18, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Sains Hayat", "topik": "4.0 Interaksi antara Hidupan", "standardKandungan": "4.2 Interaksi antara Tumbuhan", "standardPembelajaran": "4.2.2 Menjelaskan melalui contoh jenis interaksi simbiosis antara tumbuhan. 4.2.3 Menjelaskan pemerhatian tentang interaksi antara tumbuhan secara kreatif.", "objektifPembelajaran": "Di akhir PdP, murid dapat menjelaskan dua jenis simbiosis tumbuhan (komensalisme dan parasitisme) berserta contoh tumbuhan yang betul (m/s 62-63 Buku Teks) serta membina Kod QR rujukan video secara berkumpulan.", "kriteriaKejayaan": "Murid boleh membezakan antara hubungan komensalisme (langsuyar/orkid pada pokok perumah) dengan parasitisme (bunga pakma/dedalu pada pokok perumah) dari aspek kesan kepada pokok perumah dengan tepat.", "setInduksi": "Guru menunjukkan gambar bunga pakma (Rafflesia) yang besar menempel pada akar pokok lain dan bertanya bagaimana ia mendapatkan makanan sedangkan ia tidak mempunyai daun hijau untuk fotosintesis.", "penyampaian": ["Guru menerangkan jenis Simbiosis Tumbuhan berdasarkan Buku Teks m/s 62-63:", "Murid dibahagikan kepada kumpulan untuk menjalankan 'Aktiviti Ria: Kod QR Video Interaksi antara Tumbuhan' (Buku Teks m/s 64).", "Setiap kumpulan mencari pautan video berkaitan simbiosis tumbuhan di internet, menukarkan pautan tersebut menjadi kod QR menggunakan laman web penjana kod QR, mencetaknya, dan menampalkannya di sudut pameran kelas.", "Murid menjalankan aktiviti mengimbas kod QR kumpulan rakan lain dan menonton video interaksi tumbuhan menggunakan peranti mudah alih."], "penutup": "Murid membuat rumusan kognitif tentang kepentingan mengekalkan simbiosis tumbuhan untuk menjaga keaslian dan keseimbangan ekosistem hutan hujan tropika.", "pentaksiran": "Penghasilan dan kefahaman bahan rujukan video melalui kod QR.", "bahanBantuBelajar": "Komputer/peranti mudah alih, penjana kod QR, gam, kertas, Buku Teks m/s 62-64.", "refleksi": ""}, {"id": 37, "title": "Ulang Kaji Tema 1: Inkuiri dalam Sains", "minggu": 19, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Inkuiri dalam Sains", "topik": "Ulang Kaji Tema 1: Inkuiri dalam Sains", "standardKandungan": "Pengukuhan Kemahiran Saintifik dan Peraturan Bilik Sains", "standardPembelajaran": "Ulang kaji Standard Pembelajaran di bawah Unit 1 (Kemahiran Saintifik) dan Unit 2 (Peraturan Bilik Sains).", "objektifPembelajaran": "Di akhir PdP, murid dapat menyelesaikan sekurang-kurangnya 4 soalan mencabar berkaitan kemahiran proses sains dan peraturan bilik sains dalam 'Asah Minda' (Buku Teks m/s 11-12) dengan betul.", "kriteriaKejayaan": "Murid boleh mengira kadar tindak balas, menulis hipotesis munasabah bagi cecair mengalir (susu vs syampu - m/s 11), dan mengelas haiwan Pak Teh dengan tepat.", "setInduksi": "Guru membentangkan papan kuiz interaktif bertajuk \"Cabaran Saintis Cilik\" untuk mengimbas kembali topik-topik awal penggal.", "penyampaian": ["Murid dibahagikan kepada kumpulan kecil untuk menganalisis soalan 'Asah Minda' Unit 1 (Buku Teks m/s 11-12).", "Murid membincangkan Soalan 1 tentang pemboleh ubah dalam penuaian padi (menggunakan sabit vs jentera).", "Murid menyelesaikan Soalan 3 tentang menuang 100 ml susu segar (2 saat) dan syampu (8 saat) di dalam silinder penyukat bagi menulis hipotesis hubungan kelikatan cecair dengan masa mengalir (m/s 11).", "Murid menyelesaikan Soalan 4 mengelas haiwan peliharaan Pak Teh (angsa, kambing, lembu, ayam) mengikut ciri sepunya cara membiak (bertelur vs melahirkan anak) menggunakan carta pengelasan (m/s 12).", "Guru menyemak jawapan murid dan memberikan pembetulan bagi sebarang salah faham konsep KPS."], "penutup": "Murid membuat refleksi tentang kepentingan menguasai kemahiran saintifik sebagai persediaan menghadapi pentaksiran sains akan datang.", "pentaksiran": "Semakan lembaran kerja jawapan 'Asah Minda' Unit 1.", "bahanBantuBelajar": "Kad soalan kuiz, Buku Teks m/s 11-12.", "refleksi": ""}, {"id": 38, "title": "Ulang Kaji Tema 2: Sains Hayat", "minggu": 19, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Sains Hayat", "topik": "Ulang Kaji Tema 2: Sains Hayat", "standardKandungan": "Pengukuhan Pembiakan Manusia, Sistem Saraf, Mikroorganisma, dan Interaksi", "standardPembelajaran": "Ulang kaji kandungan Standard Kandungan di bawah Unit 2 (Manusia), Unit 3 (Mikroorganisma), dan Unit 4 (Interaksi Antara Hidupan).", "objektifPembelajaran": "Di akhir PdP, murid dapat menyelesaikan teka-teki istilah dan soalan struktur pengukuhan bertajuk 'Asah Minda' Unit 2, 3, dan 4 dengan betul.", "kriteriaKejayaan": "Murid boleh menjelaskan proses persenyawaan manusia, menamakan 5 jenis mikroorganisma, dan memadankan jenis interaksi simbiosis haiwan dengan tepat.", "setInduksi": "Guru memainkan permainan bingo pantas \"Ayuh, Bingo!\" (Buku Teks m/s 29) menggunakan 25 istilah berkaitan pembiakan manusia untuk mengaktifkan ingatan jangka panjang murid.", "penyampaian": ["Murid membincangkan soalan latihan Unit 2 'Manusia' (m/s 31-32) berkaitan fungsi organ pembiakan lelaki dan perempuan.", "Murid mengulas jawapan Unit 3 'Mikroorganisma' (m/s 50) tentang mengenal pasti jenis mikroorganisma berdasarkan ciri yang diberikan (contoh: paling seni = virus, membiak melalui spora = fungi).", "Murid membincangkan soalan latihan Unit 4 'Interaksi antara Hidupan' (m/s 66) untuk memadankan jenis hubungan (mangsa-pemangsa, persaingan, simbiosis) dengan contoh yang sesuai.", "Murid menulis jawapan lengkap dalam buku latihan secara individu di bawah pemantauan bimbingan guru."], "penutup": "Murid merumuskan kejayaan menguasai konsep-konsep asas Sains Hayat yang kritikal bagi memahami keseimbangan sistem kehidupan.", "pentaksiran": "Buku latihan latihan bertulis ulang kaji.", "bahanBantuBelajar": "Kad istilah bingo, lembaran soalan, Buku Teks m/s 29, 31, 50, 66.", "refleksi": ""}, {"id": 39, "title": "5.0 Pemeliharaan dan Pemuliharaan", "minggu": 20, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Sains Hayat", "topik": "5.0 Pemeliharaan dan Pemuliharaan", "standardKandungan": "5.1 Pemeliharaan dan Pemuliharaan", "standardPembelajaran": "5.1.1 Menyatakan maksud pemeliharaan dan pemuliharaan haiwan dan tumbuhan. 5.1.3 Menjelas dengan contoh haiwan yang pupus.", "objektifPembelajaran": "Di akhir PdP, murid dapat menyatakan definisi pemeliharaan, pemuliharaan, dan kepupusan serta menyenaraikan sekurang-kurangnya 5 contoh haiwan yang telah pupus dengan betul berdasarkan Buku Teks m/s 68-69.", "kriteriaKejayaan": "Murid boleh membezakan istilah 'pupus' (lenyap sama sekali dari muka bumi) dengan 'terancam' (bilangan berkurang hampir pupus) dan menyatakan contoh haiwan pupus seperti dodo, mamot, dan quagga dengan tepat.", "setInduksi": "Guru menunjukkan video lakonan realiti maya (Buku Teks m/s 67) yang memaparkan landskap purba Bumi dipenuhi dinosaur dan gajah besar (mamot), bertanya mengapa kita tidak dapat melihat haiwan tersebut hidup hari ini.", "penyampaian": ["Guru menerangkan definisi Pupus iaitu telah lenyap sama sekali dari muka Bumi.", "Murid mengkaji 5 contoh haiwan pupus di m/s 68-69 Buku Teks:", "Murid secara berpasangan membina peta minda kronologi kepupusan haiwan purba dalam bentuk kad grafik."], "penutup": "Murid merumuskan maksud Pemeliharaan (mengekalkan keadaan asal seimbang) dan Pemuliharaan (mengembalikan kepada keadaan asal) sebagai benteng menghalang sejarah kepupusan berulang pada spesies haiwan moden.", "pentaksiran": "Lembaran kerja membina definisi pemeliharaan/pemuliharaan dan contoh haiwan pupus.", "bahanBantuBelajar": "Gambar haiwan pupus m/s 68-69, kad istilah, Buku Teks m/s 68-69.", "refleksi": ""}, {"id": 40, "title": "5.0 Pemeliharaan dan Pemuliharaan", "minggu": 20, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Sains Hayat", "topik": "5.0 Pemeliharaan dan Pemuliharaan", "standardKandungan": "5.1 Pemeliharaan dan Pemuliharaan", "standardPembelajaran": "5.1.2 Menjana idea cara pemeliharaan dan pemuliharaan haiwan dan tumbuhan.", "objektifPembelajaran": "Di akhir PdP, murid dapat menjana sekurang-kurangnya 4 cara pemeliharaan dan 2 cara pemuliharaan hidupan liar dengan betul berdasarkan Buku Teks m/s 75-79.", "kriteriaKejayaan": "Murid boleh mencadangkan amalan pemeliharaan (pembalakan terpilih, undang-undang, kitar semula) dan pemuliharaan (pusat pemulihan orang utan/penyu, penanaman semula pokok) yang relevan untuk mengatasi ancaman.", "setInduksi": "Guru mempamerkan sekeping kertas kosong dan sehelai beg plastik guna semula, bertanya murid bagaimana mengurangkan penggunaan kedua-dua bahan ini dapat menyelamatkan hutan dan hidupan liar.", "penyampaian": ["Murid meneliti cara Pemeliharaan di m/s 75-77 Buku Teks: pembalakan terpilih, mendidik masyarakat (Kempen Hari Hidupan Liar), memboikot produk spesies terancam (telur penyu), menguatkuasakan undang-undang perlindungan, mengitar semula barangan (menyelamatkan pokok), dan mewartakan hutan simpan/taman marin/tapak RAMSAR.", "Murid meneliti cara Pemuliharaan di m/s 78-79 Buku Teks: membina pusat pemuliharaan (seperti Pusat Pemulihan Orang Utan Sepilok di Sabah, pusat penetasan penyu) dan menanam semula pokok di kawasan hutan yang musnah.", "Murid secara berkumpulan membincangkan tugasan menyusun klasifikasi amalan pemeliharaan vs pemuliharaan di atas papan putih menggunakan carta klasifikasi."], "penutup": "Murid membuat refleksi kognitif bahawa tanggungjawab pemeliharaan dan pemuliharaan bermula daripada pilihan harian diri sendiri, contohnya tidak menyokong pembelian barangan berasaskan spesies terancam.", "pentaksiran": "Kuiz padanan kaedah perlindungan (pemeliharaan vs pemuliharaan).", "bahanBantuBelajar": "Kad amalan m/s 75-79, beg plastik mesra alam, kertas kitar semula, Buku Teks m/s 75-79.", "refleksi": ""}, {"id": 41, "title": "5.0 Pemeliharaan dan Pemuliharaan", "minggu": 21, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Sains Hayat", "topik": "5.0 Pemeliharaan dan Pemuliharaan", "standardKandungan": "5.1 Pemeliharaan dan Pemuliharaan", "standardPembelajaran": "5.1.4 Menjelas melalui contoh haiwan dan tumbuhan yang diancam kepupusan.", "objektifPembelajaran": "Di akhir PdP, murid dapat menyenaraikan sekurang-kurangnya 5 contoh haiwan dan 5 contoh tumbuhan yang terancam serta menjelaskan mengapa hidupan bersaiz besar lebih berisiko mengalami ancaman kepupusan berdasarkan m/s 70-71 Buku Teks.", "kriteriaKejayaan": "Murid boleh menyatakan contoh hidupan terancam di Malaysia seperti Harimau Malaya, tapir, periuk kera, orkid selipar, dan bunga pakma dengan betul.", "setInduksi": "Guru menunjukkan gambar Harimau Malaya dan bunga pakma. Murid bersoal jawab mengapa hidupan ini disenaraikan sebagai spesies terancam dalam akhbar tempatan.", "penyampaian": ["Murid meneliti teks m/s 70-71 Buku Teks untuk memahami istilah Ancaman Kepupusan (keadaan di mana bilangan spesies hidupan semakin berkurang dan hampir lenyap).", "Murid mengenal pasti senarai haiwan terancam: burung kenyalang, harimau Malaya, gajah, beruang panda, tapir Malaya, badak sumbu, orang utan, dan dugong.", "Murid mengenal pasti senarai tumbuhan terancam: periuk kera, orkid selipar, pokok tongkat ali, bunga pakma, pokok meranti, pokok cengal, dan pokok keruing.", "Guru membimbing murid menjawab soalan KBAT m/s 71: \"Mengapakah haiwan bersaiz besar lebih berisiko untuk diancam kepupusan?\" (Sebab: Haiwan besar memerlukan saiz habitat yang luas untuk memburu, mencari makanan, dan membiak berbanding haiwan kecil - m/s 401).", "Murid secara berpasangan membina kad padanan foto hidupan terancam berserta namanya."], "penutup": "Murid merumuskan kepentingan melindungi spesies terancam ini agar ekosistem hutan kekal seimbang.", "pentaksiran": "Senarai padanan spesies terancam dalam buku latihan.", "bahanBantuBelajar": "Foto hidupan terancam m/s 70-71, Buku Teks m/s 70-71.", "refleksi": ""}, {"id": 42, "title": "5.0 Pemeliharaan dan Pemuliharaan", "minggu": 21, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Sains Hayat", "topik": "5.0 Pemeliharaan dan Pemuliharaan", "standardKandungan": "5.1 Pemeliharaan dan Pemuliharaan", "standardPembelajaran": "5.1.5 Memerihalkan faktor yang menyebabkan haiwan dan tumbuhan diancam kepupusan. 5.1.6 Menjana idea kesan pemeliharaan dan pemuliharaan. 5.1.7 Menjelaskan pemerhatian tentang pemeliharaan dan pemuliharaan melalui lakaran, TMK, penulisan atau lisan secara kreatif.", "objektifPembelajaran": "Di akhir PdP, murid dapat menerangkan 5 faktor utama ancaman kepupusan dan menjalankan projek pameran visual 'Faktor Pencemaran' mengikut langkah m/s 82-83 Buku Teks dengan betul.", "kriteriaKejayaan": "Murid boleh menyenaraikan faktor ancaman (pemusnahan habitat, pemburuan haram, pencemaran, bencana alam, pemanasan global) dan menerangkan idea kesan pemeliharaan/pemuliharaan dengan tepat.", "setInduksi": "Guru menunjukkan sebotol minyak masak terpakai yang dituang sedikit ke dalam air dan bertanya murid tentang kesan tumpahan minyak tersebut terhadap haiwan akuatik.", "penyampaian": ["Murid meneliti teks 'Faktor-faktor Ancaman' m/s 72-74 Buku Teks: pemusnahan habitat (pembalakan, pembangunan), pemburuan haram (untuk hiasan/perubatan), pencemaran (sisa toksik/plastik), bencana alam (banjir, tanah runtuh), dan pemanasan global (meleburkan ais di kutub).", "Murid membincangkan kesan positif pemeliharaan/pemuliharaan m/s 80-81: mengelakkan kepupusan, memastikan hidupan tidak dieksploitasi melampau, mengekalkan persekitaran bersih, dan mengelakkan kehilangan habitat.", "Murid secara berkumpulan menjalankan 'Aktiviti Ria: Pameran Visual Ancaman Kepupusan' (Buku Teks m/s 82-83) bagi stesen 'Pencemaran'.", "Murid menghias bekas kaca dengan air, model ikan/penyu, dan memasukkan sisa plastik, penyedut minuman, serta lapisan minyak masak untuk mewakili tumpahan minyak di laut.", "Murid membentangkan visual tersebut (Gallery Walk) serta mencadangkan kaedah pemeliharaan/pemuliharaan yang sesuai bagi mengatasi pencemaran."], "penutup": "Murid membuat kesimpulan kognitif tentang kepentingan kelestarian alam sekitar demi generasi masa hadapan (m/s 83).", "pentaksiran": "Pembentangan pameran visual faktor ancaman kepupusan.", "bahanBantuBelajar": "Bekas kaca, model haiwan, sisa plastik, minyak masak, air, Buku Teks m/s 72-83.", "refleksi": ""}, {"id": 43, "title": "6.0 Daya", "minggu": 22, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Sains Fizikal", "topik": "6.0 Daya", "standardKandungan": "6.1 Daya dan Kesannya", "standardPembelajaran": "6.1.1 Menyatakan maksud daya (tarikan dan tolakan) dengan menjalankan aktiviti.", "objektifPembelajaran": "Di akhir PdP, murid dapat menyatakan definisi daya dan mengelaskan 6 aktiviti harian kepada daya tarikan atau daya tolakan dengan betul berdasarkan halaman 88-89 Buku Teks.", "kriteriaKejayaan": "Murid boleh membuktikan kewujudan daya tarikan (mendekatkan objek) dan daya tolakan (menjauhi objek) melalui 6 aktiviti ringkas 'Mari Uji' dengan tepat.", "setInduksi": "Guru meminta seorang murid bertugas menolak dan menarik pintu bilik sains secara bergilir-gilir, bertanya murid tentang perbezaan fizikal kesan kedua-dua tindakan tersebut.", "penyampaian": ["Murid meneliti halaman m/s 88-89 Buku Teks. Guru menerangkan maksud Daya iaitu tarikan atau tolakan yang bertindak ke atas sesuatu objek.", "Murid dibahagikan kepada kumpulan kecil untuk menjalankan 'Mari Uji: Daya Tarikan dan Daya Tolakan' (Buku Teks m/s 89).", "Murid menjalankan 6 aktiviti stesen:", "Murid mencatatkan pemerhatian ke dalam jadual pengelasan daya tarikan, tolakan, atau kedua-duanya sekali (seperti menarik zip/memampat spring)."], "penutup": "Murid merumuskan maksud daya tarikan (objek mendekati kita) dan daya tolakan (objek menjauhi kita) serta menjawab soalan KBAT m/s 89: daya graviti Bumi adalah jenis daya tarikan kerana ia menarik semua objek ke arah pusat Bumi.", "pentaksiran": "Jadual klasifikasi tindakan tarikan dan tolakan.", "bahanBantuBelajar": "Bekas pensel, spring, bola pingpong, magnet bar, klip kertas, Buku Teks m/s 88-89.", "refleksi": ""}, {"id": 44, "title": "6.0 Daya", "minggu": 22, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Sains Fizikal", "topik": "6.0 Daya", "standardKandungan": "6.1 Daya dan Kesannya", "standardPembelajaran": "6.1.2 Menjelas dengan contoh kesan daya (ubah bentuk, arah, kelajuan, gerak/henti objek). 6.1.3 Menjelaskan pemerhatian tentang daya secara kreatif melalui lakaran, penulisan, TMK atau lisan.", "objektifPembelajaran": "Di akhir PdP, murid dapat menerangkan 5 jenis kesan daya dengan memberikan contoh harian munasabah dan menyediakan slaid pembentangan digital secara berkumpulan (Buku Teks m/s 90-92).", "kriteriaKejayaan": "Murid boleh menyatakan sekurang-kurangnya 4 daripada 5 kesan daya (mengubah bentuk, mengubah arah, mengubah kelajuan, menggerakkan objek pegun, menghentikan objek bergerak) dengan betul.", "setInduksi": "Guru menekan tiub ubat gigi kosong di hadapan kelas sehingga bentuknya kemik dan bertanya: \"Apakah kesan fizikal yang terhasil apabila saya mengenakan daya pada tiub ini?\"", "penyampaian": ["Murid meneliti rajah visual 'Kesan Daya' m/s 90-91 Buku Teks:", "Murid dibimbing memahami aktiviti 'Aktiviti Ria: Kenal Pasti dan Jelaskan Kesan Daya' (Buku Teks m/s 92).", "Murid secara individu/berkumpulan mengambil gambar aktiviti fizikal sendiri yang menunjukkan kesan daya (seperti memicit plastisin atau menyepak bola).", "Murid memindahkan gambar tersebut ke dalam perisian *Google Slides* atau *Microsoft PowerPoint* dan membentangkan rumusan kesan daya di hadapan kelas secara lisan yang kreatif."], "penutup": "Murid membuat kesimpulan bahawa walaupun daya itu sendiri tidak kelihatan, kesan-kesan daya dapat diperhatikan dan dirasai dengan jelas pada perubahan objek.", "pentaksiran": "Penilaian slaid pembentangan digital Kesan Daya.", "bahanBantuBelajar": "Tiub ubat gigi, plastisin, kamera/peranti, slaid persembahan, Buku Teks m/s 90-92.", "refleksi": ""}, {"id": 45, "title": "6.0 Daya", "minggu": 23, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Sains Fizikal", "topik": "6.0 Daya", "standardKandungan": "6.2 Daya Geseran", "standardPembelajaran": "6.2.1 Menyatakan maksud daya geseran dengan menjalankan aktiviti. 6.2.2 Memerihalkan kesan daya geseran.", "objektifPembelajaran": "Di akhir PdP, murid dapat menyatakan definisi daya geseran, arah tindakannya, serta menjelaskan 4 kebaikan dan 4 keburukan daya geseran dalam kehidupan harian (Buku Teks m/s 93-96).", "kriteriaKejayaan": "Murid boleh menyatakan arah daya geseran sentiasa bertentangan dengan arah pergerakan objek dan melengkapkan jadual banding beza kebaikan/keburukan geseran dengan tepat.", "setInduksi": "Guru mencuba menyalakan sebatang mancis (m/s 95) dengan menggoresnya pada permukaan kotak mancis, bertanya kepada murid bagaimana haba dan api boleh terhasil.", "penyampaian": ["Murid merujuk rajah pergerakan skuter di m/s 93 Buku Teks untuk memahami konsep Daya Geseran iaitu daya yang terhasil apabila dua permukaan bersentuhan antara satu sama lain, sentiasa bertindak bertentangan arah gerakan.", "Murid merancang aktiviti 'Mari Uji: Daya Geseran' menggunakan aplikasi inklinometer pada telefon pintar untuk mengukur sudut kecondongan menggelongsor bagi pemadam dan pengasah pensel (m/s 94).", "Murid mengkaji Kebaikan Kesan Geseran di m/s 95: pemadam memadam tulisan, pad brek menghentikan basikal, kertas pasir melicinkan kayu, corak tayar menambah cengkaman.", "Murid mengkaji Keburukan Kesan Geseran di m/s 96: tapak kasut haus (menyebabkan tergelincir), bunyi kuat kerja menggerudi (pencemaran bunyi), enjin kereta mudah rosak, skru berkarat sukar dilonggarkan.", "Murid melengkapkan 'Aktiviti Ria: Kesan Daya Geseran di Sekeliling Saya' dengan menulis kesan geseran pada nota berpelekat dan mengasingkannya kepada lajur 'Kebaikan' dan 'Keburukan' di atas kad manila (m/s 96)."], "penutup": "Murid membuat kesimpulan bahawa daya geseran memberi dwi-kesan (kebaikan dan keburukan) yang mempengaruhi kecekapan aktiviti harian kita.", "pentaksiran": "Tugasan klasifikasi kebaikan dan keburukan kesan geseran pada kad manila.", "bahanBantuBelajar": "Kotak mancis, pemadam, papan klip, telefon pintar (inklinometer), nota berpelekat, Buku Teks m/s 93-96.", "refleksi": ""}, {"id": 46, "title": "6.0 Daya", "minggu": 23, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Sains Fizikal", "topik": "6.0 Daya", "standardKandungan": "6.2 Daya Geseran", "standardPembelajaran": "6.2.3 Mengeksperimen untuk menentukan faktor yang mempengaruhi daya geseran (jisim, jenis permukaan).", "objektifPembelajaran": "Di akhir PdP, murid dapat menghubungkaitkan faktor jisim objek dan faktor jenis permukaan dengan kekuatan daya geseran melalui dua eksperimen lengkap di m/s 97-98 Buku Teks dengan betul.", "kriteriaKejayaan": "Murid boleh membuktikan bahawa semakin bertambah jisim objek, semakin bertambah daya geseran; dan semakin kasar jenis permukaan, semakin bertambah daya geseran.", "setInduksi": "Guru mencuba menolak sebuah kerusi kosong dan sebuah kerusi yang diduduki oleh seorang murid di atas lantai makmal, meminta murid menerangkan mengapa kerusi berpenumpang sukar digerakkan.", "penyampaian": ["Eksperimen 1 (Jisim Objek - m/s 97): Murid menggunakan susunan takal, benang, dan pemberat 50g untuk menarik sebuah buku latihan di atas meja. Murid merekodkan jumlah pemberat yang diperlukan untuk menggerakkan buku latihan kosong vs buku latihan yang ditambah buku teks tebal di atasnya (Buku Teks m/s 97).", "Murid mentafsirkan data: Buku dengan tambahan buku teks tebal memerlukan bilangan pemberat yang lebih banyak kerana jisim bertambah menyebabkan daya geseran bertambah.", "Eksperimen 2 (Jenis Permukaan - m/s 98): Murid meletakkan kadbod secara condong di atas buku untuk dijadikan landasan bagi meluncurkan sel kering. Murid mengukur jarak yang dilalui oleh sel kering di atas empat permukaan berbeza: kertas, kain, kertas pasir, dan permaidani kecil.", "Murid mentafsirkan data: Sel kering bergerak paling jauh di atas kertas (licin/geseran rendah) dan paling dekat di atas kertas pasir/permaidani (kasar/geseran tinggi - m/s 98)."], "penutup": "Murid membina laporan eksperimen bertulis yang merumuskan hubungan jisim dan kekasaran permukaan dengan daya geseran.", "pentaksiran": "Laporan eksperimen faktor mempengaruhi daya geseran.", "bahanBantuBelajar": "Takal, pemberat 50g, buku latihan, buku teks tebal, pembaris meter, sel kering, kertas, kertas pasir, kain, permaidani, Buku Teks m/s 97-98.", "refleksi": ""}, {"id": 47, "title": "6.0 Daya", "minggu": 24, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Sains Fizikal", "topik": "6.0 Daya", "standardKandungan": "6.2 Daya Geseran", "standardPembelajaran": "6.2.4 Menjana idea untuk menyelesaikan masalah tentang daya geseran dalam kehidupan harian.", "objektifPembelajaran": "Di akhir PdP, murid dapat menjana sekurang-kurangnya 3 idea mengurangkan daya geseran dan 3 idea menambah daya geseran bagi menyelesaikan masalah harian dengan betul berdasarkan Buku Teks m/s 99-100.", "kriteriaKejayaan": "Murid boleh memadankan penyelesaian masalah (contoh: minyak pelincir untuk rantai ketat, bedak untuk papan karom, pelilinan) dengan betul mengikut situasinya.", "setInduksi": "Guru menunjukkan rantai basikal yang kering, berkarat, dan berbunyi bising semasa dikayuh, meminta murid mencadangkan kaedah mekanikal untuk mengatasi masalah tersebut.", "penyampaian": ["Murid meneliti situasi mengurangkan geseran di m/s 99 Buku Teks: menggunakan minyak pelincir pada rantai basikal, menyapu bedak/tepung pada papan karom, dan memasang roda pada troli untuk memindahkan kotak berat.", "Murid meneliti situasi menambah geseran di m/s 100 Buku Teks: menggunakan kain untuk membuka penutup botol yang ketat, menggunakan berus kasar untuk membersihkan kotoran lantai, dan memasang grip pada pemegang raket untuk mengelakkan raket terlepas.", "Guru mengemukakan info sains m/s 99 tentang Kereta api Maglev yang menggunakan daya tolakan elektromagnet untuk melayang di atas landasan, menyingkirkan geseran fizikal bagi mencapai kelajuan tinggi.", "Murid secara berpasangan membincangkan kaedah menyelesaikan situasi lain (contoh: meletakkan lilin pada laci kayu yang ketat)."], "penutup": "Murid merumuskan bahawa pengurusan daya geseran (menambah atau mengurang) adalah sangat penting untuk memastikan kecekapan fungsi mekanikal harian.", "pentaksiran": "Lembaran kerja bertulis situasi dan kaedah menyelesaikan masalah geseran.", "bahanBantuBelajar": "Minyak pelincir, penutup botol ketat, kain, bedak karom, Buku Teks m/s 99-100.", "refleksi": ""}, {"id": 48, "title": "6.0 Daya", "minggu": 24, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Sains Fizikal", "topik": "6.0 Daya", "standardKandungan": "6.2 Daya Geseran", "standardPembelajaran": "6.2.5 Menjelaskan pemerhatian tentang daya geseran secara kreatif melalui lakaran, penulisan, TMK atau lisan.", "objektifPembelajaran": "Di akhir PdP, murid dapat mengenal pasti masalah geseran dan membentangkan draf penyelesaian masalah tersebut secara grafik berkumpulan mengikut langkah Buku Teks m/s 100.", "kriteriaKejayaan": "Murid boleh mempamerkan sekurang-kurangnya tiga contoh foto masalah geseran beserta cadangan penyelesaian konkrit pada papan pembentangan secara kemas.", "setInduksi": "Guru menayangkan gambar tayar kereta yang botak bunga tayarnya dan bertanya murid tentang risiko keselamatan yang dihadapi oleh pemandu semasa hujan lebat.", "penyampaian": ["Murid dibimbing untuk merancang aktiviti berdasarkan 'Aktiviti Ria: Tiada Masalah Geseran' (Buku Teks m/s 100).", "Secara berpasangan, murid menggunakan enjin carian internet untuk mencari gambar-gambar yang menunjukkan masalah harian berkaitan daya geseran (tapak kasut haus, engsel pintu berbunyi, papan gelongsor kasar).", "Murid mencetak gambar tersebut, menampalnya di atas kad manila, dan menulis analisis kaedah mengatasinya secara terperinci.", "Murid mempersembahkan hasil kerja mereka kepada rakan sekelas melalui pembentangan ringkas bertajuk \"Inovasi Mengatasi Geseran\"."], "penutup": "Murid membuat refleksi tentang peranan teknologi dalam memanipulasi geseran untuk memudahkan pergerakan dan memelihara keselamatan manusia.", "pentaksiran": "Penilaian hasil kerja kreatif poster \"Tiada Masalah Geseran\".", "bahanBantuBelajar": "Komputer, mesin cetak, kad manila, gunting, gam, Buku Teks m/s 100.", "refleksi": ""}, {"id": 49, "title": "6.0 Daya", "minggu": 25, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Sains Fizikal", "topik": "6.0 Daya", "standardKandungan": "6.3 Tekanan Udara", "standardPembelajaran": "6.3.1 Memerihalkan kewujudan tekanan udara di sekeliling dengan menjalankan aktiviti. 6.3.2 Menghubungkaitkan antara tekanan udara dengan aras ketinggian.", "objektifPembelajaran": "Di akhir PdP, murid dapat membuktikan kewujudan tekanan udara melalui amali kad tebal dan cawan air, serta menerangkan hubungan antara tekanan udara dengan aras ketinggian dengan betul (Buku Teks m/s 101-106).", "kriteriaKejayaan": "Murid boleh menyatakan hipotesis: \"Semakin bertambah ketinggian suatu tempat dari aras laut, semakin berkurang tekanan udara\" berdasarkan pemahaman bilangan zarah udara di atmosfera (m/s 106).", "setInduksi": "Guru menunjukkan belon yang mengembang (m/s 101) dan menerangkan peranan perlanggaran zarah-zarah udara rawak dengan permukaan belon yang menghasilkan tekanan udara.", "penyampaian": ["Mari Uji Aktiviti 1 (m/s 103): Murid mengisi cawan kaca dengan air sehingga penuh, menutupnya dengan kad tebal, menterbalikkannya secara perlahan di atas singki, dan memerhatikan kad tebal tidak jatuh kerana ditolak oleh tekanan udara luar ke atas.", "Murid menyiasat kesan ketinggian di m/s 105: botol plastik kosong ditutup ketat di puncak Gunung Kinabalu (tekanan udara rendah) menjadi kemik apabila dibawa turun ke kaki gunung (tekanan udara tinggi menolak dinding luar botol).", "Murid menjalankan 'Mari Uji: Simulasi Perubahan Tekanan Udara' menggunakan kubus span dan pemberat 100g untuk menggambarkan pengedaran zarah udara mengikut ketinggian (m/s 106).", "Murid merumuskan bahawa di kawasan tinggi (puncak gunung), bilangan zarah udara adalah sedikit, maka kekerapan perlanggaran zarah berkurang menyebabkan tekanan udara menjadi rendah (m/s 194/106)."], "penutup": "Murid melukis draf gambar rajah perbandingan zarah udara di puncak gunung vs kaki gunung lengkap dengan anak panah penunjuk tekanan udara.", "pentaksiran": "Lembaran kerja hubung kait ketinggian dengan tekanan udara.", "bahanBantuBelajar": "Cawan kaca, kad tebal, air, botol plastik kemik, kubus span, pemberat 100g, Buku Teks m/s 101-106.", "refleksi": ""}, {"id": 50, "title": "6.0 Daya", "minggu": 25, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Sains Fizikal", "topik": "6.0 Daya", "standardKandungan": "6.3 Tekanan Udara", "standardPembelajaran": "6.3.3 Menjelas melalui contoh aplikasi tekanan udara dalam kehidupan harian. 6.3.4 Menjelaskan pemerhatian tentang tekanan udara secara kreatif melalui lakaran, penulisan, TMK atau lisan.", "objektifPembelajaran": "Di akhir PdP, murid dapat menjelaskan prinsip kerja 4 alat aplikasi tekanan udara (tin ditebuk 2 lubang, sifon, picagari, pelocok) dan menjalankan amali penyedut minuman melintang di m/s 107-109 Buku Teks dengan betul.", "kriteriaKejayaan": "Murid boleh menerangkan mengapa tin susu yang ditebuk dua lubang membolehkan cecair mengalir keluar dengan lancar berbanding satu lubang sahaja menggunakan konsep tekanan udara.", "setInduksi": "Guru mencuba menyedut air menggunakan penyedut minuman yang mempunyai lubang kecil di bahagian tengahnya, bertanya murid mengapa air gagal naik ke dalam mulut.", "penyampaian": ["Murid meneliti rajah 'Aplikasi Tekanan Udara' m/s 107-108 Buku Teks:", "Murid menjalankan amali 'Mari Uji: Aplikasi Tekanan Udara' (m/s 108-109): memotong dua penyedut minuman (A dan B), memasukkan penyedut A secara menegak dalam air, mendekatkan penyedut B secara melintang di atasnya, menghembus dengan kuat menerusi B, dan memerhatikan semburan air yang naik dari A akibat zon tekanan rendah yang terhasil di muncung A.", "Murid melakarkan arah aliran udara dan air bagi eksperimen penyedut minuman tersebut secara kreatif dalam buku nota."], "penutup": "Murid merumuskan kepentingan aplikasi tekanan udara dalam menyelesaikan pelbagai masalah sanitasi dan pemindahan cecair harian.", "pentaksiran": "Lakaran rajah prinsip kerja penyedut minuman melintang.", "bahanBantuBelajar": "Penyedut minuman, gelas, air, gunting, tin susu kosong, Buku Teks m/s 107-109.", "refleksi": ""}, {"id": 51, "title": "7.0 Kelajuan", "minggu": 26, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Sains Fizikal", "topik": "7.0 Kelajuan", "standardKandungan": "7.1 Kelajuan Objek", "standardPembelajaran": "7.1.1 Menyatakan unit bagi kelajuan ($km/j$, $m/s$, $cm/s$).", "objektifPembelajaran": "Di akhir PdP, murid dapat menyatakan maksud kelajuan dan menulis unit kelajuan yang sesuai bagi tiga situasi pergerakan objek (siput, pelari, kereta) dengan betul berdasarkan halaman 114-115 Buku Teks.", "kriteriaKejayaan": "Murid boleh menyatakan maksud kelajuan (ukuran kepantasan pergerakan suatu objek dari satu tempat ke tempat lain) dan menukar unit perkaitan jarak dan masa secara teori dengan tepat.", "setInduksi": "Guru menunjukkan gambar perlumbaan haiwan antara kura-kura dengan citah, bertanya murid haiwan manakah yang akan menamatkan perlumbaan terlebih dahulu dan apakah ukuran kuantitatif kepantasannya.", "penyampaian": ["Murid membaca teks m/s 114 Buku Teks untuk memahami konsep Kelajuan (ukuran kepantasan pergerakan objek).", "Guru menerangkan tiga unit piawai kelajuan berserta contoh kegunaan yang logik:", "Murid menjalankan 'Aktiviti Ria: Unit Kelajuan' (Buku Teks m/s 115) secara berpasangan dengan mencari maklumat kelajuan haiwan atau kenderaan di internet dan membina jadual perbandingan unit dalam buku latihan.", "Murid membincangkan soalan KBAT m/s 115: \"Mengapakah unit cm/s tidak sesuai digunakan untuk mengukur kelajuan kereta?\" (Sebab: Jarak pergerakan kereta adalah sangat jauh, maka unit km/j adalah lebih praktikal untuk mengelakkan nilai angka yang terlalu besar - m/s 405)."], "penutup": "Murid membuat rumusan bertulis tentang kaitan unit kelajuan dengan gandingan unit jarak (cm, m, km) dan unit masa (s, minit, j).", "pentaksiran": "Jadual padanan unit kelajuan dengan objek bergerak.", "bahanBantuBelajar": "Komputer/peranti internet, kad gambar haiwan/kenderaan, Buku Teks m/s 113-115.", "refleksi": ""}, {"id": 52, "title": "7.0 Kelajuan", "minggu": 26, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Sains Fizikal", "topik": "7.0 Kelajuan", "standardKandungan": "7.1 Kelajuan Objek", "standardPembelajaran": "7.1.2 Mengeksperimen untuk menentukan hubungan antara kelajuan, jarak dan masa.", "objektifPembelajaran": "Di akhir PdP, murid dapat mengeksperimen hubungan antara kelajuan dengan masa bagi jarak yang ditetapkan mengikut langkah m/s 117 Buku Teks dengan betul.", "kriteriaKejayaan": "Murid boleh membuktikan hipotesis: \"Semakin bertambah kelajuan objek, semakin berkurang masa yang diambil untuk bergerak dalam jarak yang ditetapkan\" melalui plot graf eksperimen yang tepat.", "setInduksi": "Guru meletakkan landasan pembaris condong dan meluncurkan sebiji guli, bertanya murid: \"Bagaimanakah kita boleh meningkatkan kelajuan guli ini untuk sampai ke hujung landasan dalam masa yang lebih singkat?\"", "penyampaian": ["Murid merancang 'Eksperimen: Hubungan antara Kelajuan dengan Masa' (Buku Teks m/s 117) untuk mengkaji kesan ketinggian landasan (kelajuan) terhadap masa pergerakan guli bagi jarak landasan 1 meter (PD).", "Murid membina landasan menggunakan pembaris beralur di tengah yang disokong oleh bilangan buku sebagai PM (1 buah buku, 3 buah buku, 5 buah buku).", "Murid melepaskan guli dari atas landasan dan mencatatkan masa pergerakan guli (PB) menggunakan jam randik sehingga guli menyentuh kadbod di garisan penamat.", "Murid mengulangi langkah eksperimen, merekodkan data masa ke dalam jadual, dan memplot graf bilangan buku (mewakili kelajuan) melawan perubahan masa."], "penutup": "Murid merumuskan bahawa objek yang bergerak lebih laju akan mengambil masa yang lebih singkat untuk sampai ke destinasi bagi suatu jarak yang tetap (m/s 116).", "pentaksiran": "Plot graf dan penulisan laporan eksperimen hubungan kelajuan dan masa.", "bahanBantuBelajar": "Pembaris beralur, guli, jam randik, kadbod, buku rujukan tebal, Buku Teks m/s 116-117.", "refleksi": ""}, {"id": 53, "title": "7.0 Kelajuan", "minggu": 27, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Sains Fizikal", "topik": "7.0 Kelajuan", "standardKandungan": "7.1 Kelajuan Objek", "standardPembelajaran": "7.1.3 Menyelesaikan masalah berkaitan kelajuan menggunakan rumus.", "objektifPembelajaran": "Di akhir PdP, murid dapat menyelesaikan sekurang-kurangnya 3 jenis masalah pengiraan matematik melibatkan kelajuan, jarak, dan masa menggunakan rumus yang betul (Buku Teks m/s 119-121).", "kriteriaKejayaan": "Murid boleh menulis rumus Kelajuan ($K = J \\div M$), Jarak ($J = K \\times M$), dan Masa ($M = J \\div K$) serta menghitung jawapan dengan tepat beserta unit piawai yang betul.", "setInduksi": "Guru memaparkan situasi: Sebuah kereta api laju bergerak sejauh 250 km dalam masa 2 jam, mencabar murid menghitung kepantasannya dalam masa 1 jam (m/s 120).", "penyampaian": ["Guru memperkenalkan segitiga rumus kelajuan (Jarak di puncak, Kelajuan dan Masa di tapak) untuk memudahkan hafalan rumus murid.", "Murid membincangkan Penyelesaian 1 (m/s 120): Mengira kelajuan kereta api ($250\\text{ km} \\div 2\\text{ jam} = 125\\text{ km/j}$).", "Murid membincangkan Penyelesaian 2 (m/s 120-121): Mengira jarak yang dilalui oleh skuter papan roda selama 1 minit dengan kelajuan $5\\text{ m/s}$. Guru membimbing murid menukar unit masa terlebih dahulu (1 minit = 60 saat), seterusnya menghitung jarak ($5\\text{ m/s} \\times 60\\text{ s} = 300\\text{ m}$).", "Murid membincangkan Penyelesaian 3 (m/s 121): Mengira masa pergerakan kereta yang dipandu sejauh 10 km dengan kelajuan $50\\text{ km/j}$ dalam unit minit ($10\\text{ km} \\div 50\\text{ km/j} = 0.2\\text{ jam} \\times 60\\text{ minit} = 12\\text{ minit}$).", "Murid menyelesaikan soalan latihan pengukuhan mandiri dalam buku latihan."], "penutup": "Murid merumuskan kepatuhan menukarkan unit masa/jarak mengikut keseragaman unit kelajuan adalah kunci ketepatan jalan pengiraan sains.", "pentaksiran": "Ujian bertulis pengiraan rumus kelajuan.", "bahanBantuBelajar": "Carta formula kelajuan, Buku Teks m/s 119-121.", "refleksi": ""}, {"id": 54, "title": "7.0 Kelajuan", "minggu": 27, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Sains Fizikal", "topik": "7.0 Kelajuan", "standardKandungan": "7.1 Kelajuan Objek", "standardPembelajaran": "7.1.4 Mendefinisi secara operasi kelajuan dengan menjalankan aktiviti. 7.1.5 Menjelaskan pemerhatian tentang kelajuan secara kreatif.", "objektifPembelajaran": "Di akhir PdP, murid dapat mendefinisikan secara operasi kelajuan individu berdasarkan aktiviti larian padang dan membina carta palang keputusan mengikut langkah m/s 122 Buku Teks dengan betul.", "kriteriaKejayaan": "Murid boleh menyatakan definisi operasi kelajuan individu (ditunjukkan oleh masa yang diambil oleh pelari untuk merentasi setiap jarak stesen larian di padang) dengan tepat.", "setInduksi": "Murid berkumpul di padang sekolah dengan memakai pakaian sukan lengkap, bersedia untuk amali larian pecut.", "penyampaian": ["Murid merancang 'Mari Uji: Kelajuan Saya' (Buku Teks m/s 122). Seorang murid dilantik sebagai pelari, manakah 4 orang murid lain bertindak sebagai pencatat masa di stesen A (50m), stesen B (100m), stesen C (150m), dan stesen D (200m).", "Pelari berlari dari garisan permulaan sehingga ke garisan penamat (stesen D). Pencatat masa menghentikan jam randik masing-masing apabila pelari melintasi stesen mereka.", "Murid merekodkan data masa ke dalam jadual pengiraan (m/s 122) dan mengira kelajuan sebenar pelari di setiap sela stesen.", "Murid kembali ke bilik sains untuk membina carta palang perbandingan kelajuan bagi setiap stesen dan membincangkan soalan: \"Apakah definisi secara operasi bagi kelajuan dalam aktiviti ini?\" (m/s 122)."], "penutup": "Murid membentangkan keputusan kumpulan dan merumuskan faktor keletihan fizikal pelari boleh mempengaruhi pola penurunan kelajuan di stesen akhir (stesen D).", "pentaksiran": "Carta palang dan penulisan definisi secara operasi kelajuan pelari.", "bahanBantuBelajar": "Jam randik, pita ukur padang, skital penanda stesen, Buku Teks m/s 122.", "refleksi": ""}, {"id": 55, "title": "8.0 Teknologi Pengawetan Makanan", "minggu": 28, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Sains Bahan", "topik": "8.0 Teknologi Pengawetan Makanan", "standardKandungan": "8.1 Kerosakan Makanan", "standardPembelajaran": "8.1.1 Menjelas dengan contoh ciri makanan yang telah rosak.", "objektifPembelajaran": "Di akhir PdP, murid dapat mengenal pasti dan memerihalkan ciri-ciri kerosakan pada 5 jenis makanan (susu, roti/nasi, buah/sayur, daging, makanan laut) melalui deria penglihatan, bau, rasa, dan sentuhan dengan betul (Buku Teks m/s 128-129).", "kriteriaKejayaan": "Murid boleh menyenaraikan ciri makanan rosak seperti berbuih/berketul (susu), tompok hitam (roti), berlendir/berbau busuk (daging), dan lembik/melekit (ikan) dengan tepat.", "setInduksi": "Guru menunjukkan sekotak susu segar yang masam dan berketul di hadapan kelas, meminta murid menerangkan perubahan ciri fizikal yang mereka kesan tanpa meminumnya.", "penyampaian": ["Murid meneliti teks 'Kerosakan Makanan' m/s 128-129 Buku Teks untuk memahami ciri-ciri makanan yang telah rosak.", "Guru menerangkan ciri kerosakan secara spesifik bagi setiap kumpulan makanan:", "Murid secara berpasangan membina peta minda ringkas memadankan jenis makanan dengan ciri kerosakan fizikalnya."], "penutup": "Murid merumuskan bahawa mengesan ciri makanan rosak melalui deria adalah kaedah pertahanan semula jadi badan untuk mengelakkan penyakit keracunan makanan.", "pentaksiran": "Lembaran kerja mencatat ciri-ciri kerosakan makanan.", "bahanBantuBelajar": "Gambar makanan rosak m/s 128-129, Buku Teks m/s 128-129.", "refleksi": ""}, {"id": 56, "title": "8.0 Teknologi Pengawetan Makanan", "minggu": 28, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Sains Bahan", "topik": "8.0 Teknologi Pengawetan Makanan", "standardKandungan": "8.1 Kerosakan Makanan", "standardPembelajaran": "8.1.2 Menyatakan bahawa kerosakan makanan disebabkan oleh tindakan mikroorganisma. 8.1.3 Menjelaskan pemerhatian tentang kerosakan makanan secara kreatif.", "objektifPembelajaran": "Di akhir PdP, murid dapat menerangkan bahawa kerosakan makanan berpunca daripada tindakan penguraian mikroorganisma dan membentangkan hasil pemerhatian amali kerosakan makanan seminggu mengikut m/s 130 Buku Teks.", "kriteriaKejayaan": "Murid boleh menyatakan maksud proses penguraian (proses bahan organik diuraikan oleh bakteria/kulat kepada bahan ringkas - m/s 128) dan membentangkan rumusan pemerhatian secara berkumpulan dengan tepat.", "setInduksi": "Guru menunjukkan roti yang ditumbuhi kulapuk tebal di bawah kanta pembesar, bertanya murid: \"Apakah tindakan biologi yang sedang dilakukan oleh kulat ini ke atas roti?\"", "penyampaian": ["Guru menerangkan punca utama kerosakan makanan iaitu tindakan mikroorganisma (bakteria dan kulat) yang menjalankan proses Penguraian bahan organik kepada bentuk ringkas (m/s 128).", "Murid membincangkan keputusan 'Aktiviti Ria: Ciri-ciri Makanan Rosak' (m/s 130) yang telah disimpan di dalam bekas bertutup rapat selama seminggu (roti, sayur, buah, keju, ayam mentah).", "Murid mencatat dan mengomunikasikan perubahan fizikal hari pertama vs hari ketujuh ke dalam jadual (m/s 130).", "Murid menjalankan aktiviti pembentangan kumpulan (Gallery Walk) berkongsi hasil pemerhatian kerosakan daging ayam yang berbau busuk dan berlendir akibat terdedah pada suhu persekitaran yang sesuai (m/s 129)."], "penutup": "Murid membuat refleksi kognitif bahawa kehadiran air, udara, dan suhu hangat adalah faktor penyumbang utama yang mempercepatkan tindakan kerosakan oleh kuman.", "pentaksiran": "Jadual laporan pemerhatian kerosakan makanan hari pertama vs hari ketujuh.", "bahanBantuBelajar": "Bekas makanan, sampel makanan terurai, kanta pembesar, Buku Teks m/s 128-130.", "refleksi": ""}, {"id": 57, "title": "8.0 Teknologi Pengawetan Makanan", "minggu": 29, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Sains Bahan", "topik": "8.0 Teknologi Pengawetan Makanan", "standardKandungan": "8.2 Pengawetan Makanan", "standardPembelajaran": "8.2.1 Memerihalkan tujuan pengawetan makanan. 8.2.2 Menghubungkait kaedah pengawetan dengan faktor yang mempengaruhi pertumbuhan mikroorganisma.", "objektifPembelajaran": "Di akhir PdP, murid dapat menerangkan tujuan pengawetan makanan dan menghubungkaitkan sekurang-kurangnya 6 kaedah pengawetan dengan faktor pertumbuhan mikroorganisma yang disingkirkan dengan betul (Buku Teks m/s 131-134).", "kriteriaKejayaan": "Murid boleh menyatakan tujuan pengawetan (menghalang/melambatkan pertumbuhan mikroorganisma agar makanan tahan lama - m/s 131) dan menjelaskan prinsip sains bagi kaedah pengeringan, pembungkusan vakum, pempasteuran, dan penjerukan.", "setInduksi": "Guru menunjukkan sebotol nanas segar dan sebotol nanas jeruji (mangga jeruji), bertanya murid mengapa mangga jeruji boleh bertahan berbulan-bulan tanpa rosak.", "penyampaian": ["Guru menerangkan maksud Pengawetan Makanan (proses melambatkan kerosakan dengan menghalang pertumbuhan bakteria/kulat - m/s 131).", "Murid mengkaji 11 Kaedah Pengawetan Makanan di m/s 131-134 Buku Teks dan menghubungkaitkannya dengan faktor pertumbuhan kuman yang disekat:", "Murid secara berpasangan membina jadual padanan kaedah pengawetan vs faktor pertumbuhan mikroorganisma."], "penutup": "Murid merumuskan bahawa pengawetan memanipulasi keperluan asas mikroorganisma untuk menghalang mereka bertumbuh pada makanan.", "pentaksiran": "Lembaran kerja bertulis hubung kait kaedah pengawetan dengan prinsip sains.", "bahanBantuBelajar": "Susu kotak, jeruk mangga, cili kering, ikan masin, Buku Teks m/s 131-134.", "refleksi": ""}, {"id": 58, "title": "8.0 Teknologi Pengawetan Makanan", "minggu": 29, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Sains Bahan", "topik": "8.0 Teknologi Pengawetan Makanan", "standardKandungan": "8.2 Pengawetan Makanan", "standardPembelajaran": "8.2.3 Menjalankan projek pengawetan sejenis makanan dengan pelbagai kaedah.", "objektifPembelajaran": "Di akhir PdP, murid dapat menjalankan satu daripada 4 kaedah projek 'Pengawetan Cili' (Pengeringan, Penjerukan, Penyejukbekuan, Pendidihan) secara berkumpulan mengikut langkah Buku Teks m/s 135-138 dengan betul dan selamat.", "kriteriaKejayaan": "Murid boleh menyatakan faktor pertumbuhan mikroorganisma yang dikawal bagi kaedah pengawetan pilihan mereka dengan tepat.", "setInduksi": "Guru menunjukkan 150g cili segar berwarna merah menyala dan bertanya: \"Bagaimanakah kita boleh mengawet cili ini menggunakan empat kaedah yang berbeza agar ia tidak rosak dalam tempoh sebulan?\"", "penyampaian": ["Guru membahagikan kelas kepada 4 kumpulan utama untuk menjalankan 'Projek Pengawetan Cili' (m/s 135-138 Buku Teks):", "Murid mempraktikkan peraturan keselamatan: memakai sarung tangan plastik semasa mencuci/memotong cili dan berhati-hati mengendalikan dapur gas/pisau.", "Murid melengkapkan draf laporan amali projek masing-masing beserta jawapan soalan kefahaman faktor pertumbuhan (contoh: minyak dalam pendidihan bertindak menghalang kemasukan udara - m/s 138)."], "penutup": "Murid membuat rumusan bahawa sejenis makanan (seperti cili) boleh diawet menggunakan pelbagai kaedah pengawetan yang berbeza bergantung kepada keperluan kegunaannya.", "pentaksiran": "Penilaian amali projek Pengawetan Cili dan pembentangan laporan.", "bahanBantuBelajar": "Cili segar, penimbang, balang kaca, cuka, gula, garam, beg plastik berzip, minyak masak, pengisar, Buku Teks m/s 135-138.", "refleksi": ""}, {"id": 59, "title": "8.0 Teknologi Pengawetan Makanan", "minggu": 30, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Sains Bahan", "topik": "8.0 Teknologi Pengawetan Makanan", "standardKandungan": "8.2 Pengawetan Makanan", "standardPembelajaran": "8.2.4 Merumuskan bahawa satu jenis makanan boleh diawet dengan menggunakan pelbagai kaedah pengawetan. 8.2.5 Mengitlak bahawa makanan boleh diawet dengan menggabungkan lebih daripada satu kaedah pengawetan.", "objektifPembelajaran": "Di akhir PdP, murid dapat menjalankan amali mengawet ikan dengan menggabungkan kaedah pemasinan dan pengeringan mengikut langkah 'Mari Uji' m/s 139 Buku Teks dengan betul.", "kriteriaKejayaan": "Murid boleh mengitlak kelebihan menggabungkan lebih daripada satu kaedah pengawetan (seperti garam pekat + jemur matahari) untuk meningkatkan tempoh ketahanan makanan dengan tepat.", "setInduksi": "Guru menunjukkan seekor ikan kering masam dan bertanya murid: \"Apakah dua kaedah pengawetan berbeza yang digabungkan secara serentak untuk menghasilkan ikan kering ini?\"", "penyampaian": ["Murid meneliti arahan 'Mari Uji: Gabungan Kaedah Pengawetan Makanan' (m/s 139 Buku Teks).", "Murid secara berkumpulan menjalankan amali mengawet ikan:", "Murid membincangkan fungsi kuantiti garam yang banyak (menyingkirkan kelembapan dalam makanan - m/s 139/257).", "Murid mengitlak bahawa gabungan kaedah (pemasinan + pengeringan) menghasilkan kesan sinergi yang menyingkirkan kelembapan dengan lebih menyeluruh, menyekat pembiakan bakteria secara total."], "penutup": "Murid merumuskan contoh makanan lain yang menggunakan gabungan kaedah (contoh: nanas dalam tin yang melibatkan pendidihan dan pengetinan).", "pentaksiran": "Laporan bertulis eksperimen gabungan pengawetan ikan masin.", "bahanBantuBelajar": "Dua ekor ikan segar, garam halus, dawai pelapik, pisau, Buku Teks m/s 139.", "refleksi": ""}, {"id": 60, "title": "8.0 Teknologi Pengawetan Makanan", "minggu": 30, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Sains Bahan", "topik": "8.0 Teknologi Pengawetan Makanan", "standardKandungan": "8.2 Pengawetan Makanan", "standardPembelajaran": "8.2.6 Memerihalkan kepentingan teknologi pengawetan makanan bagi memenuhi keperluan bekalan makanan. 8.2.7 Menjelaskan pemerhatian tentang pengawetan makanan secara kreatif.", "objektifPembelajaran": "Di akhir PdP, murid dapat menerangkan 6 kepentingan teknologi pengawetan makanan bagi memenuhi bekalan makanan manusia dengan betul berdasarkan m/s 140-142 Buku Teks.", "kriteriaKejayaan": "Murid boleh memberikan hujah rasional kepentingan pengawetan (bertahan lama, elak pembaziran, mudah disimpan, bekalan luar musim, eksport, sedia dimakan) dengan tepat.", "setInduksi": "Guru menunjukkan sepaket pek makanan kembara sedia dimakan (MRE) yang digunakan oleh tentera atau pendaki gunung, bertanya murid bagaimana teknologi ini membantu mereka bertahan dalam situasi ekstrem.", "penyampaian": ["Murid meneliti teks 'Kepentingan Teknologi Pengawetan' m/s 140-142 Buku Teks:", "Murid membincangkan info sains m/s 142 tentang kepentingan menyemak tarikh luput (*use by date*) sebelum makan makanan diawet.", "Murid dibahagikan kepada kumpulan untuk melengkapkan risalah kreatif bertajuk \"Sains di Sebalik Pengawetan Makanan\"."], "penutup": "Murid membuat kesimpulan tentang bagaimana teknologi pengawetan menyokong sekuriti makanan global.", "pentaksiran": "Risalah kreatif kumpulan mengenai kepentingan pengawetan makanan.", "bahanBantuBelajar": "Sampel makanan dalam tin, pek MRE, Buku Teks m/s 140-142.", "refleksi": ""}, {"id": 61, "title": "9.0 Bahan Buangan", "minggu": 31, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Sains Bahan", "topik": "9.0 Bahan Buangan", "standardKandungan": "9.1 Pengurusan Bahan Buangan", "standardPembelajaran": "9.1.1 Mengenal pasti bahan buangan berdasarkan jenis bahan.", "objektifPembelajaran": "Di akhir PdP, murid dapat mengenal pasti dan mengkategorikan pelbagai bahan buangan kepada 7 jenis bahan (kaca, logam, kertas, tinja, plastik, sisa makanan, sisa toksik) dengan betul berdasarkan halaman 148-149 Buku Teks.", "kriteriaKejayaan": "Murid boleh menyenaraikan sekurang-kurangnya satu contoh harian yang munasabah bagi setiap satu daripada 7 kategori bahan buangan tersebut.", "setInduksi": "Guru menunjukkan gambar pemandangan laut yang tercemar dengan botol plastik, jala tersangkut, dan penyu (m/s 147), lalu meminta murid berbincang tentang apa yang mereka rasa apabila melihat situasi tersebut.", "penyampaian": ["Murid meneliti teks m/s 148 Buku Teks untuk memahami maksud Bahan Buangan iaitu bahan yang tidak diperlukan dan tidak mahu disimpan lagi.", "Guru menerangkan 7 kategori bahan buangan berserta contohnya:", "Murid secara berpasangan melengkapkan draf pengelasan bahan buangan yang dikesan di sekitar kawasan kantin sekolah."], "penutup": "Murid merumuskan kepentingan mengenali kategori bahan buangan bagi memudahkan amalan pengasingan sisa di peringkat punca.", "pentaksiran": "Peta pemikiran jenis-jenis bahan buangan.", "bahanBantuBelajar": "Tin aluminium, botol kaca, surat khabar, botol plastik, Buku Teks m/s 147-149.", "refleksi": ""}, {"id": 62, "title": "9.0 Bahan Buangan", "minggu": 31, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Sains Bahan", "topik": "9.0 Bahan Buangan", "standardKandungan": "9.1 Pengurusan Bahan Buangan", "standardPembelajaran": "9.1.2 Menyatakan maksud bahan buangan terbiodegradasi dan tidak terbiodegradasi. 9.1.3 Mengelaskan bahan buangan kepada kategori terbiodegradasi dan tidak terbiodegradasi.", "objektifPembelajaran": "Di akhir PdP, murid dapat membezakan antara bahan terbiodegradasi dengan tidak terbiodegradasi berdasarkan keupayaan penguraian oleh mikroorganisma serta mengelaskan 10 bahan buangan dengan betul (Buku Teks m/s 150-151).", "kriteriaKejayaan": "Murid boleh menyatakan maksud terbiodegradasi (boleh diuraikan oleh bakteria/fungi) dan tidak terbiodegradasi (tidak boleh diuraikan oleh kuman) dengan tepat.", "setInduksi": "Guru menunjukkan sekeping kertas yang separuh hancur di dalam tanah dan sekeping beg plastik yang masih utuh di dalam tanah, meminta murid memberikan ulasan sains mereka.", "penyampaian": ["Murid meneliti perbualan Jesy dan ayahnya di m/s 150 Buku Teks tentang pengasingan sisa.", "Guru menerangkan definisi Bahan Buangan Terbiodegradasi (bahan organik yang boleh diuraikan oleh bakteria/fungi, mengembalikan nutrien ke dalam tanah - m/s 150). Contoh: sisa makanan, kertas, daun kering, tinja.", "Guru menerangkan definisi Bahan Buangan Tidak Terbiodegradasi (bahan sintetik yang tidak boleh diuraikan oleh kuman, terus kekal di persekitaran untuk tempoh yang lama - m/s 151). Contoh: plastik, logam, kaca, sisa toksik.", "Murid menjalankan 'Aktiviti Ria: Bahan Buangan Terbiodegradasi dan Tidak Terbiodegradasi' (Buku Teks m/s 151). Murid mencari gambar bahan buangan di internet, mencetaknya, dan mengelaskannya ke dalam bentuk draf carta pengelasan di atas kadbod secara kreatif."], "penutup": "Murid membuat kesimpulan kognitif tentang perbezaan ketara proses penguraian biologi antara kedua-dua kumpulan sisa tersebut.", "pentaksiran": "Carta pengelasan bahan terbiodegradasi vs tidak terbiodegradasi.", "bahanBantuBelajar": "Sampel sampah harian, kadbod, gunting, gam, Buku Teks m/s 150-151.", "refleksi": ""}, {"id": 63, "title": "9.0 Bahan Buangan", "minggu": 32, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Sains Bahan", "topik": "9.0 Bahan Buangan", "standardKandungan": "9.1 Pengurusan Bahan Buangan", "standardPembelajaran": "9.1.4 Menaakul penggunaan bahan terbiodegradasi dan tidak terbiodegradasi secara berhemah.", "objektifPembelajaran": "Di akhir PdP, murid dapat menaakul kepentingan penggunaan bahan terbiodegradasi dan tidak terbiodegradasi secara berhemah demi mengelakkan pencemaran air, banjir kilat, dan kemusnahan hidupan akuatik berdasarkan situasi Buku Teks m/s 152-154.", "kriteriaKejayaan": "Murid boleh menerangkan sekurang-kurangnya dua akibat buruk sekiranya sisa tidak terurai dibuang secara sembarangan ke dalam longkang atau sungai.", "setInduksi": "Guru memaparkan berita tentang kes pencemaran sisa kimia berbahaya di Sungai Kim Kim, Pasir Gudang (m/s 154) dan meminta murid membincangkan impak kesihatan terhadap penduduk berhampiran.", "penyampaian": ["Murid meneliti situasi m/s 152-153 Buku Teks:", "Murid membincangkan kepentingan amalan memboikot penyedut minuman plastik bagi mengurangkan timbunan plastik di laut.", "Murid secara berkumpulan membina draf risalah kempen bertajuk \"Katakan Tidak Kepada Plastik Sekali Guna\"."], "penutup": "Murid membuat kesimpulan tentang tujuan utama penggunaan bahan secara berhemah iaitu untuk memelihara kesihatan manusia dan kelestarian ekosistem global (m/s 155).", "pentaksiran": "Pembinaan risalah kempen alam sekitar.", "bahanBantuBelajar": "Keratan akhbar Sungai Kim Kim, cawan polistirena, beg plastik, Buku Teks m/s 152-154.", "refleksi": ""}, {"id": 64, "title": "9.0 Bahan Buangan", "minggu": 32, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Sains Bahan", "topik": "9.0 Bahan Buangan", "standardKandungan": "9.1 Pengurusan Bahan Buangan", "standardPembelajaran": "9.1.5 Memerihalkan pengurusan bahan buangan secara terancang untuk kehidupan lestari. 9.1.6 Menjelaskan pemerhatian tentang pengurusan bahan buangan secara kreatif.", "objektifPembelajaran": "Di akhir PdP, murid dapat menerangkan amalan pengurusan sisa terancang di rumah (mengikat sisa kemas, membuat baja kompos, mengasing sisa, kitar semula) dan melaksanakan draf perancangan projek 5R berdasarkan Buku Teks m/s 156-161.", "kriteriaKejayaan": "Murid boleh memadankan warna tong kitar semula (biru: kertas, coklat: kaca, jingga: plastik/tin) dengan jenis bahan buangan yang betul secara tepat.", "setInduksi": "Guru menunjukkan tiga tong kitar semula berskala kecil (biru, coklat, jingga) di atas meja dan bertanya murid tentang kod warna tersebut.", "penyampaian": ["Murid meneliti contoh amalan pengurusan sisa secara terancang di m/s 156-157 Buku Teks: mengikat beg sampah dengan kemas (elak lalat/tikus), membuat baja kompos daripada sisa makanan, menggunakan bekas khas membuang sisa minyak masak, mengasingkan sisa mengikut jenis, menderma barang terpakai, dan membina peralatan kreatif (buaian tayar).", "Murid mengkaji fungsi tong kitar semula (m/s 159): Biru (kertas), Coklat (kaca), Jingga (tin aluminium/plastik).", "Murid membincangkan pelancaran 'Aktiviti Ria: Projek 5R' (Buku Teks m/s 161) merangkumi aspek: *Reduce, Reuse, Recycle, Repair, dan Refuse*.", "Setiap kumpulan merancang kempen mengumpul bahan kitar semula di kawasan rumah masing-masing sepanjang minggu depan dan melakarkan draf jadual kutipan sisa."], "penutup": "Murid membuat kesimpulan tentang kepentingan melatih diri mengurus sisa secara sistematik bagi mengurangkan limpahan sampah di tapak pelupusan akhir (m/s 160).", "pentaksiran": "Pelan rancangan Projek 5R kumpulan.", "bahanBantuBelajar": "Peta warna tong kitar semula, kertas lukisan, Buku Teks m/s 156-161.", "refleksi": ""}, {"id": 65, "title": "10.0 Gerhana", "minggu": 33, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Bumi dan Angkasa", "topik": "10.0 Gerhana", "standardKandungan": "10.1 Fenomena Gerhana", "standardPembelajaran": "10.1.1 Memerihalkan fenomena gerhana Bulan berdasarkan kedudukan Bulan, Bumi dan Matahari dengan bantuan simulasi.", "objektifPembelajaran": "Di akhir PdP, murid dapat menerangkan kedudukan jasad samawi semasa gerhana Bulan (Matahari-Bumi-Bulan) dalam satu garis lurus dan menerangkan mengapa gerhana tidak berlaku setiap bulan berdasarkan m/s 166-167 Buku Teks.", "kriteriaKejayaan": "Murid boleh melukis rajah kedudukan jasad samawi semasa gerhana Bulan secara lengkap beserta arah bayangan umbra dan penumbra dengan tepat.", "setInduksi": "Guru menayangkan gambar Bulan purnama yang perlahan-lahan bertukar warna menjadi kemerahan (m/s 166) dan bertanya murid tentang fenomena tersebut.", "penyampaian": ["Guru menerangkan bahawa Gerhana Bulan berlaku apabila Bumi berada di antara Matahari dengan Bulan dalam satu garis lurus (Buku Teks m/s 166). Bumi menghalang seluruh cahaya matahari ke Bulan dan menghasilkan bayang-bayang di atas permukaan Bulan.", "Murid mempelajari bahawa fenomena ini hanya berlaku semasa fasa Bulan purnama (m/s 166).", "Murid membincangkan mengapa gerhana Bulan tidak berlaku setiap bulan (m/s 167): Kerana orbit Bulan yang mengelilingi Bumi adalah condong kira-kira $5^\\circ$ kepada orbit Bumi yang mengelilingi Matahari, menyebabkan Bulan sering berada di atas atau di bawah bayang-bayang Bumi (m/s 167/304).", "Murid melukis draf kedudukan jasad Matahari, Bumi, dan Bulan lengkap dengan label kawasan gelap penuh (umbra) dan gelap separa (penumbra) (Buku Teks m/s 168)."], "penutup": "Murid merumuskan peranan Bumi sebagai objek legap yang menghalang cahaya matahari dalam fenomena gerhana Bulan.", "pentaksiran": "Lakaran berlabel rajah Gerhana Bulan.", "bahanBantuBelajar": "Sfera model jasad samawi, Buku Teks m/s 165-167.", "refleksi": ""}, {"id": 66, "title": "10.0 Gerhana", "minggu": 33, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Bumi dan Angkasa", "topik": "10.0 Gerhana", "standardKandungan": "10.1 Fenomena Gerhana", "standardPembelajaran": "10.1.2 Memerihalkan fenomena gerhana Matahari berdasarkan kedudukan Bulan, Bumi dan Matahari dengan bantuan simulasi. 10.1.3 Menghubungkaitkan gerhana dengan sifat cahaya.", "objektifPembelajaran": "Di akhir PdP, murid dapat menerangkan kedudukan jasad samawi semasa gerhana Matahari (Matahari-Bulan-Bumi) dalam satu garis lurus dan menghubungkaitkannya dengan sifat cahaya dengan betul (Buku Teks m/s 168-172).", "kriteriaKejayaan": "Murid boleh menyatakan dua sifat cahaya terlibat (bergerak lurus, tidak boleh menembusi objek legap - m/s 171) dan membezakan kawasan lintasan umbra dengan penumbra di Bumi dengan tepat.", "setInduksi": "Guru memancarkan cahaya lampu suluh ke arah bola plastik legap sehingga membentuk bayangan di atas dinding putih, bertanya murid sifat cahaya yang terlibat dalam proses ini.", "penyampaian": ["Guru menerangkan bahawa Gerhana Matahari berlaku apabila Bulan berada di antara Matahari dengan Bumi dalam satu garis lurus (Buku Teks m/s 168). Bulan menghalang cahaya matahari sampai ke permukaan Bumi pada fasa Bulan baharu di waktu siang (m/s 168).", "Murid mengkaji kawasan lintasan di Bumi (m/s 168): kawasan lintasan umbra (mengalami gerhana penuh) dan kawasan lintasan penumbra (mengalami gerhana separa - m/s 168/306).", "Murid menghubungkaitkan fenomena ini dengan dua sifat cahaya utama: Cahaya bergerak dalam garis lurus dan cahaya tidak dapat menembusi objek legap (Bumi/Bulan) (Buku Teks m/s 171).", "Murid melukis draf kedudukan jasad Matahari, Bulan, dan Bumi secara berskala dalam buku nota."], "penutup": "Murid membuat kesimpulan kognitif tentang perbezaan mendasar kedudukan jasad antara gerhana Bulan (Bumi di tengah) dengan gerhana Matahari (Bulan di tengah).", "pentaksiran": "Kuiz bertulis kedudukan jasad dan sifat cahaya semasa gerhana.", "bahanBantuBelajar": "Lampu suluh, bola tenis (Bumi), bola pingpong (Bulan), Buku Teks m/s 168-172.", "refleksi": ""}, {"id": 67, "title": "10.0 Gerhana", "minggu": 34, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Bumi dan Angkasa", "topik": "10.0 Gerhana", "standardKandungan": "10.1 Fenomena Gerhana", "standardPembelajaran": "10.1.4 Meramalkan keadaan di Bumi semasa kejadian gerhana.", "objektifPembelajaran": "Di akhir PdP, murid dapat meramalkan sekurang-kurangnya tiga perubahan parameter fizikal dan biologi (kecerahan, suhu, tindak balas haiwan, ketinggian air laut) semasa gerhana berlaku dengan betul berdasarkan m/s 174-175 Buku Teks.", "kriteriaKejayaan": "Murid boleh menerangkan mengapa suhu persekitaran menurun dan mengapa haiwan kembali ke sarang semasa kejadian gerhana Matahari penuh secara logik.", "setInduksi": "Guru memadamkan semua lampu bilik sains secara tiba-tiba sehingga bilik menjadi gelap seketika, bertanya murid tentang tindak balas spontan tubuh mereka terhadap perubahan kecerahan.", "penyampaian": ["Murid meneliti kronologi foto perubahan keadaan sekeliling semasa gerhana Matahari penuh m/s 174 Buku Teks:", "Murid mengkaji kesan gerhana Bulan (m/s 175) terhadap tarikan graviti gabungan yang menyebabkan kedudukan air pasang laut dikesan lebih tinggi daripada kebiasaan (m/s 320).", "Murid secara berpasangan membincangkan langkah keselamatan m/s 173: Dilarang melihat gerhana Matahari secara terus dengan mata kasar kerana boleh merosakkan retina, sebaliknya gunakan cermin mata penuras khas atau kamera lubang jarum (m/s 175).", "Murid menulis satu karangan pendek ramalan imaginatif tentang pengalaman berada di bawah bayangan umbra gerhana Matahari penuh."], "penutup": "Murid merumuskan impak nyata fenomena astromoni terhadap iklim mikro dan hidupan di Bumi.", "pentaksiran": "Karangan kreatif ramalan persekitaran semasa gerhana.", "bahanBantuBelajar": "Slaid foto gerhana, Buku Teks m/s 173-175.", "refleksi": ""}, {"id": 68, "title": "10.0 Gerhana", "minggu": 34, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Bumi dan Angkasa", "topik": "10.0 Gerhana", "standardKandungan": "10.1 Fenomena Gerhana", "standardPembelajaran": "10.1.5 Menjelaskan pemerhatian tentang gerhana secara kreatif melalui lakaran, penulisan, TMK atau lisan.", "objektifPembelajaran": "Di akhir PdP, murid dapat membina satu model simulasi gerhana Matahari dan Bulan menggunakan plastisin dan lampu suluh secara berkumpulan mengikut langkah Buku Teks m/s 109-110/170.", "kriteriaKejayaan": "Murid boleh mengoperasikan model simulasi gerhana untuk menghasilkan bayang-bayang umbra dan penumbra yang jelas di atas kad putih.", "setInduksi": "Guru mengedarkan bahan amali (lampu suluh, jarum peniti, plastisin) dan mencabar murid menghasilkan bayang-bayang separa menggunakan kepala jarum peniti.", "penyampaian": ["Murid merujuk langkah-langkah 'Mari Uji: Model Simulasi Gerhana' di m/s 170 Buku Teks.", "Murid membina model jasad samawi menggunakan bahan:", "5cm mewakili Bumi) di tengah-tengah plastik bulat (m/s 170).", "Murid menutup lampu bilik sains, meletakkan model menghadap lampu suluh (Matahari), memegang kad putih di belakangnya, menggerakkan model Bulan mengorbit Bumi, dan memerhatikan bayang-bayang gerhana Bulan serta Matahari yang terbentuk di atas kad putih (m/s 170).", "Murid membentangkan lisan hasil pemerhatian mereka tentang peranan kepala jarum peniti menghalang cahaya lampu suluh."], "penutup": "Murid membuat refleksi tentang kecekapan model fizikal dalam membantu menggambarkan pergerakan mekanikal jasad angkasa yang bersaiz mega.", "pentaksiran": "Penilaian kemahiran manipulatif amali Model Simulasi Gerhana.", "bahanBantuBelajar": "Lampu suluh, jarum peniti, plastisin, lidi, plastik lut sinar, kad putih, Buku Teks m/s 170.", "refleksi": ""}, {"id": 69, "title": "11.0 Galaksi", "minggu": 35, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Bumi dan Angkasa", "topik": "11.0 Galaksi", "standardKandungan": "11.1 Galaksi Bima Sakti", "standardPembelajaran": "11.1.1 Menyatakan maksud galaksi. 11.1.2 Memerihalkan galaksi Bima Sakti. 11.1.3 Merumuskan Sistem Suria berada dalam galaksi Bima Sakti.", "objektifPembelajaran": "Di akhir PdP, murid dapat menyatakan maksud galaksi, menerangkan bentuk galaksi Bima Sakti (pilin berpalang), dan kedudukan Sistem Suria di dalamnya dengan betul (Buku Teks m/s 180-185).", "kriteriaKejayaan": "Murid boleh menyatakan maksud galaksi (sistem yang terdiri daripada berjuta bintang, gas, debu, dan jirim - m/s 180) dan melukis peta pokok tiga bentuk galaksi (berpilin, elips, tidak sekata - m/s 182) dengan tepat.", "setInduksi": "Guru menayangkan gambar rakaman menakjubkan jaluran debu dan bintang samar-samar di langit malam (m/s 179) dan bertanya murid tentang nama jaluran tersebut (Bima Sakti).", "penyampaian": ["Guru menerangkan maksud Galaksi (m/s 180) dan mendedahkan gambar beribu-ribu titik kecil galaksi dari Teleskop Angkasa Hubble (m/s 180-181).", "Murid mempelajari tiga bentuk utama galaksi di m/s 182: galaksi berpilin (seperti Andromeda), galaksi elips, dan galaksi tidak sekata.", "Murid mengkaji struktur Galaksi Bima Sakti (m/s 183-185): sejenis galaksi pilin berpalang yang mengandungi lengan berpilin dan pusat palang bintang yang cerah dan tebal (kelihatan seperti cakera nipis membonjol di tengah dari pandangan sisi - m/s 184-185).", "Murid merumuskan kedudukan Sistem Suria (Matahari, Bumi, dan 7 planet) yang terletak di pinggir satu daripada lengan berpilin galaksi Bima Sakti (m/s 185/330)."], "penutup": "Murid membuat rumusan kognitif tentang perbandingan struktur kosmik: Bumi adalah sebahagian kecil daripada Sistem Suria, dan Sistem Suria adalah sebahagian kecil daripada Bima Sakti.", "pentaksiran": "Kuiz bertulis tentang struktur Bima Sakti dan bentuk galaksi.", "bahanBantuBelajar": "Gambar galaksi Hubble, slaid powerpoint bentuk galaksi, Buku Teks m/s 180-185.", "refleksi": ""}, {"id": 70, "title": "11.0 Galaksi", "minggu": 35, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Bumi dan Angkasa", "topik": "11.0 Galaksi", "standardKandungan": "11.1 Galaksi Bima Sakti", "standardPembelajaran": "11.1.4 Menjalankan simulasi untuk menggambarkan saiz Sistem Suria di dalam galaksi Bima Sakti. 11.1.5 Menjelaskan pemerhatian tentang galaksi Bima Sakti secara kreatif.", "objektifPembelajaran": "Di akhir PdP, murid dapat menjalankan simulasi padang untuk menggambarkan perbandingan saiz Sistem Suria di dalam Bima Sakti mengikut langkah m/s 188 Buku Teks dengan betul.", "kriteriaKejayaan": "Murid boleh mengitlak bahawa saiz Sistem Suria adalah sangat kecil (diwakili bola hoki) berbanding dengan saiz Bima Sakti (diwakili luas padang sekolah) berdasarkan simulasi dengan tepat.", "setInduksi": "Guru memegang sebatang pensel di hadapan kelas dan meminta murid membayangkan sekiranya diameter pensel adalah saiz keseluruhan Sistem Suria, berapakah pula saiz Bima Sakti? (m/s 187).", "penyampaian": ["Murid berkumpul di padang sekolah untuk menjalankan 'Mari Uji: Simulasi Saiz Sistem Suria' (Buku Teks m/s 188).", "Murid menyusun simulasi mengikut langkah m/s 188:", "Murid menganalisis perbandingan tersebut: jika bola hoki ($7.3\\text{ cm}$) mewakili Sistem Suria, kawasan padang sekolah ($60\\text{ m}$ diameter) mewakili galaksi Bima Sakti (m/s 188/335).", "Murid kembali ke kelas, melakarkan draf peta simulasi padang tersebut, dan membincangkan jawapan soalan perbandingan saiz."], "penutup": "Murid membuat kesimpulan kognitif tentang keluasan alam semesta yang menakjubkan dan saiz Bumi yang teramat seni di dalam Bima Sakti.", "pentaksiran": "Lakaran rajah simulasi padang dan jawapan soalan perbandingan saiz.", "bahanBantuBelajar": "Tepung, bola hoki, pita pengukur, skital padang, Buku Teks m/s 187-188.", "refleksi": ""}, {"id": 71, "title": "12.0 Kestabilan dan Kekuatan", "minggu": 36, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Teknologi dan Kehidupan Lestari", "topik": "12.0 Kestabilan dan Kekuatan", "standardKandungan": "12.1 Kestabilan dan Kekuatan Objek", "standardPembelajaran": "12.1.1 Memerihalkan maksud kestabilan dan kekuatan dengan menjalankan aktiviti. 12.1.2 Menjelaskan dengan contoh struktur yang kuat dan stabil.", "objektifPembelajaran": "Di akhir PdP, murid dapat menerangkan maksud kestabilan dan kekuatan objek serta memberikan 3 contoh struktur stabil dan kuat dalam kehidupan harian (Buku Teks m/s 194).", "kriteriaKejayaan": "Murid boleh menyatakan maksud kestabilan (keupayaan objek kekal/kembali ke kedudukan asal - m/s 194) dan kekuatan (keupayaan objek menampung daya tanpa rosak bentuk - m/s 199/351) dengan tepat.", "setInduksi": "Guru menceritakan kisah dongeng tiga ekor anak kambing yang membina rumah daripada jerami, kayu, dan bata yang diuji oleh serigala (Buku Teks m/s 193), meminta murid meneka mengapa rumah bata Si Bongsu terselamat.", "penyampaian": ["Guru membentangkan takrifan Kestabilan (m/s 194) dan Kekuatan (m/s 199).", "Murid mengkaji contoh kestabilan haiwan m/s 195: Zirafah mengangkangkan kedua-dua kaki hadapannya semasa minum air untuk meluaskan tapak dan merendahkan pusat graviti (ketinggian) agar lebih stabil.", "Murid menganalisis contoh struktur kuat dan stabil dalam pembinaan bersejarah: Bangunan Parlimen, Tugu Negara, dan Bangunan Sultan Abdul Samad yang kekal teguh sehingga sekarang (Buku Teks m/s 206).", "Murid secara berpasangan membina draf reka bentuk blok mainan yang stabil dengan pusat graviti yang rendah."], "penutup": "Murid merumuskan bahawa kekuatan dan kestabilan adalah asas utama dalam bidang kejuruteraan dan seni bina bagi menjamin ketahanan struktur bangunan.", "pentaksiran": "Lembaran kerja bertulis maksud kekuatan, kestabilan, dan contoh struktur.", "bahanBantuBelajar": "Blok binaan kayu, gambar zirafah m/s 195, Buku Teks m/s 193-195.", "refleksi": ""}, {"id": 72, "title": "12.0 Kestabilan dan Kekuatan", "minggu": 36, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Teknologi dan Kehidupan Lestari", "topik": "12.0 Kestabilan dan Kekuatan", "standardKandungan": "12.1 Kestabilan dan Kekuatan Objek", "standardPembelajaran": "12.1.3 Mengeksperimen untuk menentukan faktor yang mempengaruhi kestabilan objek dan binaan (luas tapak, ketinggian).", "objektifPembelajaran": "Di akhir PdP, murid dapat mengeksperimen faktor ketinggian dan luas tapak yang mempengaruhi kestabilan objek mengikut prosedur Buku Teks m/s 197-198 dengan betul.", "kriteriaKejayaan": "Murid boleh membuktikan hipotesis: \"Semakin berkurang ketinggian binaan, semakin bertambah kestabilannya\"; dan \"Semakin bertambah luas tapak binaan, semakin bertambah kestabilannya\" melalui amali.", "setInduksi": "Guru meletakkan sebuah botol plastik berisi air penuh (stabil) dan botol kosong (mudah tumbang) di atas meja, lalu bertanya murid faktor yang membezakan kestabilan kedua-dua botol tersebut semasa meja digerakkan.", "penyampaian": ["Eksperimen 1 (Ketinggian - m/s 197): Murid menyusun cawan kertas di atas kadbod secara berlapis (PM: ketinggian susunan - 1 tingkat vs 3 tingkat). Murid menggerakkan kadbod ke hadapan dan ke belakang berulang kali (PD), mencatatkan masa yang diambil apabila cawan pertama dikesan mula jatuh (PB) menggunakan jam randik.", "Murid mentafsirkan data: Susunan cawan yang tinggi (3 tingkat) cepat jatuh kerana kurang stabil (pusat graviti tinggi).", "Eksperimen 2 (Luas Tapak - m/s 197-198): Murid menggunakan tin minuman kosong untuk dibina dua model di atas kadbod: Model A dengan tapak sempit (3 tin disusun menegak), Model B dengan tapak luas (6 tin disusun bersebelahan). Murid menggerakkan kadbod dan merekodkan kestabilannya.", "Murid mentafsirkan data: Model dengan luas tapak yang besar (Model B) adalah lebih stabil dan lambat jatuh (Buku Teks m/s 198)."], "penutup": "Murid membina laporan eksperimen lengkap yang merumuskan kaitan ketinggian dan luas tapak dengan kestabilan objek.", "pentaksiran": "Laporan bertulis eksperimen faktor kestabilan objek.", "bahanBantuBelajar": "Cawan kertas, tin minuman kosong, kadbod, jam randik, Buku Teks m/s 197-198.", "refleksi": ""}, {"id": 73, "title": "12.0 Kestabilan dan Kekuatan", "minggu": 37, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Teknologi dan Kehidupan Lestari", "topik": "12.0 Kestabilan dan Kekuatan", "standardKandungan": "12.1 Kestabilan dan Kekuatan Objek", "standardPembelajaran": "12.1.4 Mengeksperimen untuk menentukan faktor yang mempengaruhi kekuatan objek dan binaan (jenis bahan, bentuk struktur).", "objektifPembelajaran": "Di akhir PdP, murid dapat mengeksperimen faktor bentuk struktur terhadap kekuatan alang kad manila mengikut langkah Buku Teks m/s 202-204 dengan betul.", "kriteriaKejayaan": "Murid boleh membina empat bentuk alang (A: dilipat, B: segi tiga, C: silinder, D: kuboid) dan menentukan alang yang paling kuat menampung beban pemberat tanpa berubah bentuk.", "setInduksi": "Guru menunjukkan sekeping kertas flat (rata) yang diletakkan di antara dua meja dan tidak mampu menyokong sebatang pensel, bertanya bagaimana kita boleh melipat kertas ini untuk menjadikannya kuat.", "penyampaian": ["Guru menerangkan faktor jenis bahan (m/s 199) di mana konkrit, besi, kayu, dan plastik mempunyai kekuatan yang berbeza.", "Murid merancang 'Eksperimen: Bentuk Struktur Binaan' (m/s 202-204 Buku Teks) untuk menguji kekuatan bentuk struktur.", "Murid membina empat jenis alang menggunakan kad manila bersaiz $24\text{ cm} \times 12\text{ cm}$:", "Murid meletakkan alang secara melintang di antara dua buah meja, menggantungkan cangkuk, menambah pemberat 10g bertahap sehingga alang berlaku perubahan bentuk/kemik, dan mencatatkan data ke dalam jadual (m/s 204)."], "penutup": "Murid mentafsirkan data dan merumuskan bentuk silinder (Alang C) adalah antara bentuk struktur paling kuat kerana pengedaran beban yang sekata (Buku Teks m/s 204).", "pentaksiran": "Laporan bertulis eksperimen bentuk struktur kekuatan.", "bahanBantuBelajar": "Kad manila, pembaris, gunting, pita pelekat, pemberat 10g, cangkuk, Buku Teks m/s 202-204.", "refleksi": ""}, {"id": 74, "title": "12.0 Kestabilan dan Kekuatan", "minggu": 37, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Teknologi dan Kehidupan Lestari", "topik": "12.0 Kestabilan dan Kekuatan", "standardKandungan": "12.1 Kestabilan dan Kekuatan Objek", "standardPembelajaran": "12.1.5 Menjana idea kepentingan binaan yang kuat dan stabil bagi menjamin kehidupan yang lestari. 12.1.6 Mencipta model binaan yang kuat dan stabil dengan menggunakan bahan kitar semula yang sesuai. 12.1.7 Menjelaskan pemerhatian tentang kestabilan dan kekuatan melalui lakaran, penulisan, TMK atau lisan secara kreatif.", "objektifPembelajaran": "Di akhir PdP, murid dapat menjana idea kepentingan binaan lestari dan melakarkan draf rancangan projek mencipta model 'Bangku Botol' yang kuat dan stabil mengikut langkah m/s 207 Buku Teks dengan betul.", "kriteriaKejayaan": "Murid boleh melakarkan reka bentuk bangku botol yang kukuh menggunakan 18 biji botol plastik dan menerangkan alasan pemilihan bahan dari aspek kestabilan dan kekuatan dengan tepat.", "setInduksi": "Guru menunjukkan sekumpulan botol plastik kosong terpakai yang dikumpulkan untuk dikitar semula, bertanya bagaimana botol-botol ini boleh ditukarkan menjadi struktur perabot bilik darjah yang kuat.", "penyampaian": ["Murid meneliti Situasi 1 & 2 di m/s 206 Buku Teks berkaitan kepentingan binaan kuat/stabil: tidak mudah rosak, menjimatkan kos baik pulih, selamat digunakan, dan bertahan lama untuk menjamin kehidupan lestari.", "Murid membincangkan perancangan 'Mencipta Model Binaan: Bangku Botol' (Buku Teks m/s 207).", "Murid melakarkan draf reka bentuk bangku botol di atas kertas lukisan secara berkumpulan dengan mengambil kira faktor luas tapak dan ketinggian (kestabilan).", "Murid menyenaraikan bahan kitar semula yang diperlukan: 18 biji botol plastik yang sama saiz, pita pelekat lebar, tuala terpakai (sebagai alas kusyen), kain, dan reben (m/s 207).", "Setiap kumpulan membentangkan draf lakaran mereka di hadapan kelas untuk mendapatkan maklum balas penambahbaikan kestabilan struktur sebelum fasa pembinaan sebenar dijalankan."], "penutup": "Murid merumuskan amalan guna semula bahan buangan plastik (upcycling) adalah tindakan menyokong kelestarian alam sekitar.", "pentaksiran": "Lakaran berlabel dan rasional reka bentuk projek Bangku Botol.", "bahanBantuBelajar": "Kertas lukisan, botol plastik kosong, pita pelekat, Buku Teks m/s 206-207.", "refleksi": ""}, {"id": 75, "title": "13.0 Teknologi", "minggu": 38, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Teknologi dan Kehidupan Lestari", "topik": "13.0 Teknologi", "standardKandungan": "13.1 Kebaikan dan Keburukan Teknologi", "standardPembelajaran": "13.1.1 Menyatakan maksud teknologi dan kepentingannya. 13.1.2 Memerihalkan perkembangan teknologi dalam pelbagai bidang.", "objektifPembelajaran": "Di akhir PdP, murid dapat menyatakan definisi teknologi dan menerangkan kemajuan teknologi dalam bidang pertanian, perubatan, pengangkutan, komunikasi, dan pembinaan dengan betul berdasarkan m/s 212-217 Buku Teks.", "kriteriaKejayaan": "Murid boleh menyenaraikan sekurang-kurangnya 5 jenis alat yang dicipta untuk mengatasi had keupayaan deria manusia (stetoskop, mikroskop, teleskop, mikrofon, telefon) berserta fungsinya secara tepat.", "setInduksi": "Guru meminta seorang murid mendengar degupan jantung rakan menggunakan telinga, kemudian memberikan stetoskop untuk membandingkan kualiti pendengaran, bertanya murid maksud had keupayaan manusia.", "penyampaian": ["Guru menerangkan definisi Teknologi iaitu aplikasi pengetahuan sains untuk membantu mengatasi had keupayaan manusia (Buku Teks m/s 212).", "Murid mengkaji jadual padanan had keupayaan vs alat di m/s 212-213: tidak boleh lihat objek seni (mikroskop), objek jauh (teleskop), suara perlahan (mikrofon/pembesar suara), dengar bunyi perlahan (stetoskop), komunikasi jauh (telefon), dan bergerak jauh dalam masa singkat (kenderaan).", "Murid membaca teks 'Perkembangan Teknologi' m/s 214-217 Buku Teks merangkumi bidang:", "Murid secara berkumpulan membina draf garisan masa sejarah perkembangan pengangkutan darat daripada kereta kuda kepada kereta api laju."], "penutup": "Murid membuat kesimpulan kognitif bahawa teknologi dicipta bertujuan untuk menjadikan kehidupan manusia lebih selesa, mudah, dan pantas.", "pentaksiran": "Lembaran kerja padanan alat dengan had keupayaan manusia.", "bahanBantuBelajar": "Stetoskop, kanta pembesar, gambar mesin MRI, Buku Teks m/s 211-217.", "refleksi": ""}, {"id": 76, "title": "13.0 Teknologi", "minggu": 38, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Teknologi dan Kehidupan Lestari", "topik": "13.0 Teknologi", "standardKandungan": "13.1 Kebaikan dan Keburukan Teknologi", "standardPembelajaran": "13.1.3 Menerangkan melalui contoh kebaikan dan keburukan teknologi dalam kehidupan harian. 13.1.4 Menjelaskan pemerhatian tentang kebaikan dan keburukan teknologi secara kreatif.", "objektifPembelajaran": "Di akhir PdP, murid dapat membahaskan kebaikan dan keburukan penggunaan teknologi (dron, ubat-ubatan, penerokaan hutan, komunikasi) dan menghasilkan peta pokok perbandingan mengikut langkah m/s 218-219 Buku Teks dengan betul.", "kriteriaKejayaan": "Murid boleh menyatakan sekurang-kurangnya 4 kebaikan dan 4 keburukan perkembangan teknologi moden terhadap kesihatan manusia dan kelestarian alam sekitar dengan tepat.", "setInduksi": "Guru menunjukkan sekotak ubat batuk dan berbincang tentang bagaimana ubat yang menyembuhkan penyakit ini boleh menjadi ancaman kesihatan sekiranya disalahgunakan.", "penyampaian": ["Murid meneliti teks 'Kebaikan dan Keburukan Teknologi' m/s 218-219 Buku Teks:", "Murid dibimbing menjalankan 'Aktiviti Ria: Kesan Teknologi' (Buku Teks m/s 219). Murid mencari maklumat tambahan di internet secara berkumpulan.", "Murid membina peta pokok kebaikan dan keburukan teknologi menggunakan aplikasi *Microsoft PowerPoint* secara kreatif dan membentangkannya di dalam kelas."], "penutup": "Murid membuat refleksi kognitif bahawa etika penggunaan teknologi oleh manusia adalah penentu sama ada teknologi memberi impak positif atau negatif kepada dunia.", "pentaksiran": "Peta pokok digital Kebaikan dan Keburukan Teknologi.", "bahanBantuBelajar": "Komputer, draf slaid powerpoint m/s 219, Buku Teks m/s 218-219.", "refleksi": ""}, {"id": 77, "title": "Pentaksiran Kertas Teori Sains Tahun 6", "minggu": 39, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Pentaksiran Akhir Tahun (PAT)", "topik": "Pentaksiran Kertas Teori Sains Tahun 6", "standardKandungan": "Penilaian Tahap Penguasaan Keseluruhan (Sains Teori)", "standardPembelajaran": "Penilaian holistik bertulis merangkumi semua standard kandungan dari Unit 1 (Kemahiran Saintifik) hingga Unit 13 (Teknologi) mengikut silibus KSSR Semakan.", "objektifPembelajaran": "Di akhir PdP, murid dapat menjawab soalan peperiksaan bertulis (objektif dan subjektif) bagi mengukur tahap pemahaman konsep-konsep sains Tahun 6 dengan jujur dan fokus.", "kriteriaKejayaan": "Murid boleh menyelesaikan kertas soalan dalam tempoh masa 1 jam 15 minit tanpa menggunakan sebarang rujukan luar secara berdikari.", "setInduksi": "Guru memberi taklimat ringkas mengenai etika menduduki pentaksiran bertulis, menyemak kehadiran murid, dan mengedarkan kertas soalan PAT Sains Tahun 6.", "penyampaian": ["Murid menyemak kelengkapan halaman kertas soalan (Bahagian A: Pilihan Ganda, Bahagian B: Soalan Struktur Kemahiran Saintifik, dan Bahagian C: Soalan Aplikasi Teori).", "Murid mula menjawab soalan secara individu dengan tenang dan fokus di bawah pengawasan ketat guru kelas.", "Murid mengaplikasikan kemahiran proses sains yang telah dipelajari sepanjang tahun (membuat inferens, mengawal pemboleh ubah, mentafsir data) untuk menjawab soalan-soalan bercorak KBAT.", "Guru mengingatkan baki masa menjawab 15 minit sebelum tamat."], "penutup": "Guru mengumpulkan semua skrip kertas jawapan murid mengikut susunan meja dan memberikan maklum balas ringkas tentang komitmen murid semasa menjawab peperiksaan.", "pentaksiran": "Kertas ujian bertulis PAT Sains Tahun 6.", "bahanBantuBelajar": "Kertas soalan PAT Sains Tahun 6, alat tulis.", "refleksi": ""}, {"id": 78, "title": "Pentaksiran Kemahiran Amali & Manipulatif", "minggu": 39, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Pentaksiran Akhir Tahun (PAT)", "topik": "Pentaksiran Kemahiran Amali & Manipulatif", "standardKandungan": "Penilaian Sikap Saintifik, Nilai Murni, dan Kemahiran Amali Sains", "standardPembelajaran": "Penilaian holistik amali berdasarkan Kemahiran Manipulatif (SP 1.2.1-1.2.5) dan KPS mengeksperimen yang telah dijalankan sepanjang tahun.", "objektifPembelajaran": "Di akhir PdP, murid dapat menjalankan satu tugasan amali ringkas yang dipilih secara rawak (contoh: Menguji Kestabilan atau Mengukur Kelajuan) serta menunjukkan amalan kemahiran manipulatif yang betul.", "kriteriaKejayaan": "Murid boleh mengendali, melakar, membersih, dan menyimpan semula peralatan sains yang digunakan dengan betul mengikut senarai semak penilaian guru.", "setInduksi": "Guru meletakkan beberapa peralatan amali (pembaris meter, silinder penyukat, bikar, plastisin, takal) di atas meja stesen dan menerangkan prosedur pentaksiran amali sains.", "penyampaian": ["Murid dibahagikan kepada giliran stesen amali secara sistematik.", "Setiap murid diberikan satu kad arahan tugasan amali ringkas (contoh: \"Uji dan bandingkan kestabilan dua tin minuman yang mempunyai luas tapak yang berbeza\").", "Murid menjalankan amali secara fizikal di bawah pemerhatian langsung guru yang mengisi borang senarai semak penilaian kendiri bagi setiap aspek:", "2.1-1.2.2).", "1.3).", "2.4).", "2.5)."], "penutup": "Guru memberikan maklum balas individu tentang kemajuan kemahiran manipulatif murid dan mengingatkan kepentingan budaya kerja selamat dalam sains.", "pentaksiran": "Senarai semak Kemahiran Manipulatif dan Amali Sains.", "bahanBantuBelajar": "Skital stesen, tin kosong, kadbod, bikar, air, silinder penyukat, borang pemantauan amali.", "refleksi": ""}, {"id": 79, "title": "Latihan Pengukuhan Kendiri di Rumah (Cuti Deepavali)", "minggu": 40, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Sains Hayat / Sains Fizikal", "topik": "Latihan Pengukuhan Kendiri di Rumah (Cuti Deepavali)", "standardKandungan": "Pengukuhan Kendiri Unit 1 hingga Unit 6", "standardPembelajaran": "Tugasan berstruktur pengukuhan kendiri bagi Standard Kandungan Pembiakan Manusia, Sistem Saraf, Mikroorganisma, Interaksi Antara Hidupan, Pemeliharaan/Pemuliharaan, dan Daya.", "objektifPembelajaran": "Di akhir cuti persekolahan, murid dapat menyiapkan draf lembaran kerja pengukuhan konsep sains fizikal dan hayat secara mandiri dengan betul di rumah.", "kriteriaKejayaan": "Murid boleh menyelesaikan sekurang-kurangnya 15 soalan struktur pengukuhan secara tepat merujuk kepada buku teks sebagai panduan belajar.", "setInduksi": "(Aktiviti sebelum cuti) Guru memberikan penerangan ringkas mengenai modul draf kerja rumah \"Pintar Sains Cuti Deepavali\" sebelum murid bercuti sempena sambutan Perayaan Deepavali.", "penyampaian": ["Murid membawa pulang modul tugasan sains yang mengandungi soalan-soalan aplikasi harian bertumpukan kemahiran sains fizikal dan hayat.", "Murid secara kendiri membaca semula draf bab Unit 2 'Sistem Saraf' dan Unit 6 'Daya' untuk melengkapkan draf penyelesaian masalah mekanikal geseran dan tekanan udara dalam modul.", "Murid dibenarkan menggunakan peranti digital di rumah untuk mengimbas kod-kod QR interaktif di dalam buku teks bagi membantu pemahaman jawapan soalan amali.", "Ibu bapa digalakkan memantau pengurusan masa anak-anak menyiapkan modul sains di rumah semasa musim cuti perayaan."], "penutup": "(Aktiviti kendiri) Murid membuat semakan draf jawapan mereka menggunakan lampiran cadangan skema jawapan ringkas di bahagian belakang modul untuk refleksi kendiri.", "pentaksiran": "Penyelesaian modul kerja rumah Pintar Sains (Semakan pasca cuti).", "bahanBantuBelajar": "Modul Pintar Sains Cuti Deepavali, Buku Teks Sains Tahun 6.", "refleksi": ""}, {"id": 80, "title": "Latihan Pengukuhan Kendiri di Rumah (Cuti Deepavali)", "minggu": 40, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Sains Fizikal / Sains Bahan", "topik": "Latihan Pengukuhan Kendiri di Rumah (Cuti Deepavali)", "standardKandungan": "Pengukuhan Kendiri Unit 7 hingga Unit 13", "standardPembelajaran": "Tugasan berstruktur pengukuhan kendiri bagi Standard Kandungan Kelajuan, Pengawetan Makanan, Bahan Buangan, Gerhana, Galaksi, Kestabilan/Kekuatan, dan Kebaikan/Keburukan Teknologi.", "objektifPembelajaran": "Di akhir cuti persekolahan, murid dapat menyiapkan draf lembaran pengiraan rumus kelajuan dan pengkelasan bahan buangan dengan betul secara mandiri di rumah.", "kriteriaKejayaan": "Murid boleh menghitung parameter jarak dan masa menggunakan rumus kelajuan ($J = K \\times M$ dan $M = J \\div K$) secara tepat mengikut latihan berstruktur.", "setInduksi": "(Aktiviti sebelum cuti) Guru memberikan taklimat draf panduan pengiraan kelajuan dan penukaran unit masa (minit ke saat, jam ke minit) untuk tugasan perayaan.", "penyampaian": ["Murid secara kendiri menyelesaikan siri 10 soalan pengiraan rumus kelajuan (Unit 7) dalam modul cuti perayaan dengan langkah pengiraan yang sistematik.", "Murid menganalisis contoh-contoh bahan buangan (Unit 9) terbiodegradasi dan tidak terbiodegradasi di rumah sendiri, lalu menyenaraikannya dalam lembaran kajian domestik modul.", "Murid membina lakaran rajah bayang-bayang umbra dan penumbra semasa gerhana Bulan (Unit 10) sebagai latihan pengukuhan visual sains Bumi dan Angkasa."], "penutup": "(Aktiviti kendiri) Murid merumuskan latihan cuti perayaan membantu mengekalkan momentum pembelajaran menjelang akhir tahun persekolahan.", "pentaksiran": "Penghantaran modul lengkap Sains Fizikal & Bahan (Semakan pasca cuti).", "bahanBantuBelajar": "Modul Pintar Sains Cuti Deepavali, Buku Teks Sains Tahun 6.", "refleksi": ""}, {"id": 81, "title": "Perbincangan Kertas Pentaksiran (Bahagian A - Pilihan Ganda)", "minggu": 41, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Analisis & Pengukuhan PAT", "topik": "Perbincangan Kertas Pentaksiran (Bahagian A - Pilihan Ganda)", "standardKandungan": "Analisis Pencapaian dan Pemulihan Teori Sains", "standardPembelajaran": "Perbincangan terperinci bagi Standard Pembelajaran yang dinilai dalam soalan objektif PAT (Unit 1 hingga Unit 13).", "objektifPembelajaran": "Di akhir PdP, murid dapat mengenal pasti sekurang-kurangnya 80% kesilapan jawapan Bahagian A mereka dan membuat pembetulan berdasarkan ulasan buku teks dengan betul.", "kriteriaKejayaan": "Murid boleh menerangkan konsep sains sebenar bagi soalan-soalan objektif yang mencatatkan peratusan kesalahan tertinggi dalam kelas.", "setInduksi": "Guru memulangkan kertas jawapan PAT yang telah disemak dan memaparkan statistik ringkas soalan Bahagian A yang paling banyak salah dijawab oleh murid.", "penyampaian": ["Guru membimbing perbincangan soalan demi soalan bagi 20 soalan pilihan ganda Bahagian A.", "Murid merujuk halaman buku teks bagi menjustifikasikan pilihan jawapan yang betul (contoh: soalan mikroorganisma paling seni merujuk kepada virus di m/s 35; soalan arah daya geseran sentiasa bertentangan gerakan di m/s 93).", "Murid membuat nota pembetulan di dalam buku latihan bagi soalan yang salah dijawab, dengan menulis penjelasan alasan sains yang betul.", "Sesi soal jawab interaktif di mana murid bertanya punca kekeliruan mereka semasa peperiksaan (contoh: mengelirukan antara hubungan mutualisme dengan komensalisme)."], "penutup": "Murid membuat refleksi kognitif bahawa peperiksaan bukan sekadar menguji kelulusan, tetapi merupakan alat diagnosis penting untuk mengenal pasti lompang kelemahan ilmu.", "pentaksiran": "Semakan pembetulan jawapan kertas Bahagian A.", "bahanBantuBelajar": "Kertas jawapan murid, Buku Teks Sains Tahun 6.", "refleksi": ""}, {"id": 82, "title": "Perbincangan Kertas Pentaksiran (Bahagian B - Kemahiran Saintifik & Subjektif)", "minggu": 41, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Analisis & Pengukuhan PAT", "topik": "Perbincangan Kertas Pentaksiran (Bahagian B - Kemahiran Saintifik & Subjektif)", "standardKandungan": "Analisis Pencapaian dan Pengayaan Kemahiran Proses Sains", "standardPembelajaran": "Perbincangan terperinci bagi soalan struktur subjektif yang menguji 12 Kemahiran Proses Sains (KPS) dalam PAT.", "objektifPembelajaran": "Di akhir PdP, murid dapat menulis draf jawapan subjektif bagi pemboleh ubah, hipotesis, inferens, dan definisi secara operasi dengan struktur penulisan sains yang betul dan jitu.", "kriteriaKejayaan": "Murid boleh membetulkan teknik penulisan hipotesis (menggunakan pola 'semakin... semakin...') dan cara menyatakan pemboleh ubah bergerak balas yang boleh diukur dengan tepat.", "setInduksi": "Guru menulis draf draf jawapan subjektif murid yang umum/lemah di papan tulis (tanpa nama murid) dan meminta murid berbincang bagaimana menukarkannya menjadi jawapan sains yang jitu.", "penyampaian": ["Guru menerangkan skema pemarkahan bagi Bahagian B dan C kertas ujian PAT Sains Tahun 6.", "Murid dibimbing menganalisis soalan kemahiran mengeksperimen (contoh: eksperimen faktor kestabilan m/s 197). Murid memperbetulkan cara menyatakan definisi secara operasi bagi kestabilan (ditunjukkan oleh masa yang diambil untuk tin tumbang).", "Murid secara berkumpulan berbincang untuk melengkapkan draf jawapan subjektif bagi soalan-soalan bercorak KBAT (seperti taakulan kepentingan pemeliharaan/pemuliharaan m/s 80).", "Murid menulis pembetulan bertulis bagi soalan Bahagian B dan C dalam buku latihan dengan kemas."], "penutup": "Murid merumuskan kepentingan ketelitian memilih kata kunci (keywords) sains yang tepat semasa menjawab soalan berbentuk subjektif.", "pentaksiran": "Semakan nota pembetulan soalan subjektif Bahagian B & C.", "bahanBantuBelajar": "Skema jawapan PAT, Buku Teks Sains Tahun 6.", "refleksi": ""}, {"id": 83, "title": "Refleksi Kendiri & Pencapaian Standard Pembelajaran Murid", "minggu": 42, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Refleksi Akhir Tahun", "topik": "Refleksi Kendiri & Pencapaian Standard Pembelajaran Murid", "standardKandungan": "Penilaian Kendiri Tahunan Pembelajaran Sains", "standardPembelajaran": "Refleksi keseluruhan pencapaian penguasaan kognitif murid bagi semua tajuk pembelajaran dari Minggu 1 hingga Minggu 41.", "objektifPembelajaran": "Di akhir PdP, murid dapat melengkapkan borang refleksi kendiri tahunan secara jujur bagi menilai kekuatan dan cabaran topik sains yang dipelajari sepanjang tahun 6.", "kriteriaKejayaan": "Murid boleh menyatakan sekurang-kurangnya tiga unit pembelajaran yang paling mereka kuasai dan dua unit yang masih memerlukan bimbingan susulan.", "setInduksi": "Guru mengedarkan sekeping kertas kad berwarna \"Exit Ticket\" dan meminta murid menulis satu ayat rumusan tentang pengalaman paling berharga mereka belajar sains di tahun 6.", "penyampaian": ["Guru memaparkan semula senarai 13 Unit Sains Tahun 6 di papan putih sebagai rujukan imbasan ingatan murid.", "Murid melengkapkan Borang Refleksi Kendiri PAT yang mengandungi senarai semak standard kandungan (SK) utama.", "Murid secara individu menulis ulasan ringkas mengenai aktiviti amali kegemaran mereka (seperti membuat Bangku Botol atau meluncurkan Kereta Belon).", "Guru mengadakan sesi temu bual ringkas bersama beberapa orang murid untuk memberikan maklum balas konstruktif tentang tahap penguasaan (TP) PBD tahunan mereka."], "penutup": "Murid merumuskan bahawa subjek Sains melatih mereka berfikir secara rasional, logik, dan kritis terhadap fenomena alam di sekeliling mereka.", "pentaksiran": "Pengisian Borang Refleksi Kendiri Murid.", "bahanBantuBelajar": "Borang refleksi kendiri, kad Exit Ticket, Buku Teks Sains.", "refleksi": ""}, {"id": 84, "title": "Pemeliharaan Kemahiran Manipulatif & Inventori Radas", "minggu": 42, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Pengurusan Bilik Sains", "topik": "Pemeliharaan Kemahiran Manipulatif & Inventori Radas", "standardKandungan": "1.2 Kemahiran Manipulatif", "standardPembelajaran": "1.2.4 Membersihkan peralatan sains dengan cara yang betul. 1.2.5 Menyimpan peralatan dan bahan sains dengan betul dan selamat.", "objektifPembelajaran": "Di akhir PdP, murid dapat mengemas, membersih, menyusun, dan mengemas kini inventori sekurang-kurangnya 5 jenis peralatan amali sains di dalam bilik sains dengan betul demi keselamatan cuti penggal akhir tahun.", "kriteriaKejayaan": "Murid boleh mempraktikkan cara mencuci bikar, membersihkan kanta mikroskop menggunakan kertas kanta, dan menyusun radas di dalam almari stor sains mengikut label keselamatan dengan kemas.", "setInduksi": "Guru menunjukkan bilik sains yang memerlukan pengemasan inventori akhir tahun dan menerangkan tanggungjawab murid menjaga kebersihan makmal tempat mereka belajar.", "penyampaian": ["Guru membahagikan kelas kepada kumpulan tugasan pengemasan Bilik Sains:", "Murid menjalankan tugasan dengan mematuhi Peraturan Bilik Sains (Unit 2) di bawah pengawasan rapi guru.", "Murid melaporkan status inventori radas yang bersih dan selamat disimpan kepada guru kelas."], "penutup": "Guru memberikan penghargaan atas kerjasama erat murid dalam menguruskan bilik sains secara lestari untuk kegunaan adik-adik darjah bawah di tahun hadapan.", "pentaksiran": "Penilaian amalan Kemahiran Manipulatif (kebersihan & penyimpanan radas makmal).", "bahanBantuBelajar": "Kertas kanta, sabun pencuci, span, kad inventori radas, Buku Teks Sains Tahun 6.", "refleksi": ""}, {"id": 85, "title": "Program Apresiasi STEM & Pembentangan Hasil Projek Terbaik", "minggu": 43, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Teknologi dan Kehidupan Lestari", "topik": "Program Apresiasi STEM & Pembentangan Hasil Projek Terbaik", "standardKandungan": "Komunikasi Kreatif Pembelajaran Sains", "standardPembelajaran": "Mempersembahkan hasil projek kreatif terbaik (seperti model Bangku Botol atau model Gerhana) sepanjang tahun secara lisan dan interaktif.", "objektifPembelajaran": "Di akhir PdP, murid dapat membentangkan 1 hasil projek STEM terbaik kumpulan mereka kepada tetamu lawatan kelas dengan penuh yakin, teratur, dan jelas.", "kriteriaKejayaan": "Murid boleh menerangkan aplikasi prinsip-prinsip sains (seperti kestabilan, kekuatan, pengawetan, atau tekanan udara) yang terdapat pada projek pembentangan mereka dengan tepat.", "setInduksi": "Guru membuka dewan pameran mini \"Sains & Inovasi 2026\" di dalam bilik sains dan menyambut kehadiran murid serta tetamu lawatan (murid Tahun 5).", "penyampaian": ["Setiap kumpulan menyusun model projek terbaik mereka di atas meja pameran (contoh: Model Bangku Botol m/s 207, Terarium Kulat m/s 47, atau Model Gerhana m/s 170).", "Murid menjalankan sesi pembentangan projek inovasi kepada tetamu pameran yang mengimbas kod-kod QR video buatan murid (Unit 4/m/s 64).", "Murid menjawab soalan-soalan teknikal sains daripada penonton (contoh: menerangkan mengapa bentuk silinder botol menjadikan bangku stabil menampung berat badan orang dewasa - m/s 207/360).", "Tetamu dan guru memberikan undian bintang kepada kumpulan pembentangan yang paling kreatif, berinformasi, dan berkualiti tinggi."], "penutup": "Guru mengumumkan pemenang anugerah \"Inovator Muda STEM 2026\" dan menyampaikan sijil apresiasi ringkas bagi menghargai komitmen murid.", "pentaksiran": "Penilaian lisan kemahiran berkomunikasi dan kualiti produk STEM.", "bahanBantuBelajar": "Model projek buatan murid, kad bintang pengundi, Buku Teks Sains.", "refleksi": ""}, {"id": 86, "title": "Pengurusan Fail & Penyerahan Rekod PBD", "minggu": 43, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Pengurusan Akhir Tahun", "topik": "Pengurusan Fail & Penyerahan Rekod PBD", "standardKandungan": "Pengurusan Fail Pembelajaran dan Penggulungan Sesi Akademik", "standardPembelajaran": "Melengkapkan pelaporan Pentaksiran Bilik Darjah (PBD) Sains Tahun 6 dan pemfailan hasil kerja murid.", "objektifPembelajaran": "Di akhir PdP, murid dapat mengemas kini draf fail portfolio kerja sains mereka secara teratur, memulangkan buku teks SPBT dalam keadaan baik, dan menerima maklum balas laporan TP PBD akhir tahun dengan gembira.", "kriteriaKejayaan": "Murid boleh menyusun semua lembaran amali, laporan eksperimen, dan ujian bulanan di dalam fail mengikut kronologi pembelajaran dari Unit 1 hingga Unit 13 dengan kemas.", "setInduksi": "Guru mengucapkan tahniah kepada semua murid kerana telah melengkapkan perjalanan pembelajaran kurikulum Sains Tahun 6 KSSR Semakan dengan jayanya sepanjang tahun 2026.", "penyampaian": ["Murid menyusun dan memfailkan semua dokumen hasil kerja sains bertulis, laporan eksperimen, lukisan draf, serta borang refleksi ke dalam fail portfolio sains peribadi masing-masing.", "Murid menyemak keadaan buku teks Sains Tahun 6 SPBT mereka (memastikan tiada koyak atau halaman hilang) sebelum bersedia untuk diserahkan semula ke unit SPBT sekolah (m/s 9-11).", "Guru mengedarkan borang pelaporan Tahap Penguasaan (TP) PBD Sains Tahun 6 murid (mengandungi rekod TP1 hingga TP6 bagi aspek kognitif, amali, dan sikap saintifik).", "Guru memberikan ulasan akhir dan pesanan motivasi peribadi kepada setiap murid untuk mengekalkan minat mendalam terhadap subjek sains/STEM apabila melangkah ke sekolah menengah (Tingkatan 1) pada tahun hadapan."], "penutup": "Murid merakamkan ucapan terima kasih kepada guru dan saling bertukar maklum balas positif sesama rakan sekelas sebelum cuti akhir persekolahan bermula pada 04 Disember 2026 (m/s 8). Sesi akademik Sains Tahun 6 ditutup secara rasmi dengan sesi bergambar kelas.", "pentaksiran": "Semakan kelengkapan fail portfolio murid.", "bahanBantuBelajar": "Fail portfolio kerja sains, borang pelaporan PBD, Buku Teks Sains Tahun 6.", "refleksi": ""}]};